# --- session_store.py ---
"""
Session Vault, Datablock Lease Table, and Atomic Context Guard for blender-kit v3.0.
Resolves OS App-Data session paths keyed to scene UUID, mirrors state into
bpy.data.texts[".blender_kit_session"], seeds template config files in zero-footprint
mode, enforces 5-role swarm datablock leases, and guards unavoidable EDIT-mode calls.
"""
import contextlib
import json
import os
import shutil
import sys
import time
import uuid
from pathlib import Path
from typing import Any, Dict, List, Optional

try:
    import bpy
except ImportError:
    bpy = None  # Allows unit testing under standard python3 with mock fixtures

LEASE_TTL_SECONDS = 300.0
_DATABLOCK_LEASES: Dict[str, Dict[str, Any]] = {}
_SESSION_TEXT_NAME = ".blender_kit_session"


def _os_appdata_root() -> Path:
    if sys.platform == "win32":
        base = os.environ.get("LOCALAPPDATA") or os.path.expanduser("~\\AppData\\Local")
    elif sys.platform == "darwin":
        base = os.path.expanduser("~/Library/Application Support")
    else:
        base = os.environ.get("XDG_STATE_HOME") or os.path.expanduser("~/.local/state")
    return Path(base) / "blender-kit" / "sessions"


def _find_templates_dir() -> Optional[Path]:
    here = Path(__file__).resolve()
    candidates = [
        here.parents[3] / "skills" / "blender-setup" / "templates",
        Path.cwd() / "skills" / "blender-setup" / "templates",
        Path.cwd() / ".agents" / "skills" / "blender-setup" / "templates",
    ]
    for c in candidates:
        if c.is_dir():
            return c
    return None


def _get_or_create_scene_uuid() -> str:
    if bpy is None or not getattr(bpy, "context", None) or not getattr(bpy.context, "scene", None):
        return "headless0001"
    scene = bpy.context.scene
    uid = scene.get("kit_session_uuid")
    if not uid or not isinstance(uid, str):
        uid = uuid.uuid4().hex[:12]
        scene["kit_session_uuid"] = uid
    return str(uid)


def _current_blend_stem() -> str:
    if bpy is not None and getattr(bpy, "data", None) and getattr(bpy.data, "filepath", ""):
        return Path(bpy.data.filepath).stem or "unsaved"
    return "unsaved"


def resolve_session_dir(asset_name: Optional[str] = None, target_mode: str = "game_realtime") -> str:
    local_cfg = Path.cwd() / "docs" / "blender" / "config.md"
    if local_cfg.is_file():
        cfg_text = local_cfg.read_text(encoding="utf-8", errors="ignore")
        if "session_storage: workspace" in cfg_text:
            base = Path.cwd() / "blender-out"
            out = base / asset_name if asset_name else base
            out.mkdir(parents=True, exist_ok=True)
            return str(out.resolve())

    root = _os_appdata_root()
    root.mkdir(parents=True, exist_ok=True)
    uid = _get_or_create_scene_uuid()
    stem = _current_blend_stem()
    desired_dir = root / f"{stem}_{uid}"

    # Match existing directory by *_<uid> suffix to preserve state across save/rename/move
    if not desired_dir.exists():
        for existing in root.glob(f"*_{uid}"):
            if existing.is_dir() and existing != desired_dir:
                try:
                    existing.rename(desired_dir)
                except OSError:
                    desired_dir = existing
                break

    desired_dir.mkdir(parents=True, exist_ok=True)
    _seed_session_config(desired_dir, target_mode=target_mode)

    if asset_name:
        asset_dir = desired_dir / "assets" / asset_name
        for sub in ("audit", "screens", "checkpoints"):
            (asset_dir / sub).mkdir(parents=True, exist_ok=True)
        return str(asset_dir.resolve())

    return str(desired_dir.resolve())


def _seed_session_config(session_dir: Path, target_mode: str = "game_realtime") -> Path:
    cfg_dir = session_dir / "config"
    cfg_dir.mkdir(parents=True, exist_ok=True)
    tpl = _find_templates_dir()
    if tpl is None:
        return cfg_dir

    for fname in ("config.md", "ground-rules.md", "assets.md"):
        src = tpl / fname
        dst = cfg_dir / fname
        if src.is_file() and not dst.exists():
            shutil.copy2(src, dst)

    eng_dst = cfg_dir / "engine.md"
    if not eng_dst.exists():
        eng_name = "film-subd.md" if target_mode == "film_cinematic" else "generic-gltf.md"
        eng_src = tpl / "engines" / eng_name
        if not eng_src.is_file():
            eng_src = tpl / "engines" / "generic-gltf.md"
        if eng_src.is_file():
            shutil.copy2(eng_src, eng_dst)

    style_dst = cfg_dir / "style.md"
    if not style_dst.exists():
        style_name = "realistic.md" if target_mode == "film_cinematic" else "lowpoly.md"
        style_src = tpl / "styles" / style_name
        if style_src.is_file():
            shutil.copy2(style_src, style_dst)

    return cfg_dir


def mirror_state_to_blend(state_update: Dict[str, Any]) -> Dict[str, Any]:
    if bpy is None or not getattr(bpy, "data", None) or not hasattr(bpy.data, "texts"):
        return state_update
    txt = bpy.data.texts.get(_SESSION_TEXT_NAME)
    if txt is None:
        txt = bpy.data.texts.new(_SESSION_TEXT_NAME)
    txt.use_fake_user = True
    current: Dict[str, Any] = {}
    raw = getattr(txt, "as_string", lambda: "")()
    if raw:
        try:
            current = json.loads(raw)
        except json.JSONDecodeError:
            current = {}
    current.update(state_update)
    current["updated_at"] = time.time()
    payload = json.dumps(current, indent=2)
    if hasattr(txt, "clear") and hasattr(txt, "write"):
        txt.clear()
        txt.write(payload)
    return current


def restore_state_from_blend() -> Dict[str, Any]:
    if bpy is None or not getattr(bpy, "data", None) or not hasattr(bpy.data, "texts"):
        return {}
    txt = bpy.data.texts.get(_SESSION_TEXT_NAME)
    if txt is None:
        return {}
    raw = getattr(txt, "as_string", lambda: "")()
    if not raw:
        return {}
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        return {}


def _prune_expired_leases() -> None:
    now = time.time()
    expired = [
        role for role, info in _DATABLOCK_LEASES.items()
        if now - info.get("acquired_at", 0.0) > info.get("ttl", LEASE_TTL_SECONDS)
    ]
    for role in expired:
        _DATABLOCK_LEASES.pop(role, None)


def verify_lease(command: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    _prune_expired_leases()
    cmd_type = command.get("type", "")
    params = command.get("params") or {}
    agent_role = params.get("agent_role", "orchestrator")

    # The auditor is read-only at all times, not only while leases are active.
    if agent_role == "auditor":
        if cmd_type in ("kit_audit_run_isolated", "get_scene_info", "get_viewport_screenshot", "get_object_info"):
            return None
        if cmd_type == "kit_session_manage" and params.get("action", "get_state") == "get_state":
            return None
        return {
            "status": "error",
            "code": "LEASE_VIOLATION",
            "message": f"Role 'auditor' is READ_ONLY and cannot execute '{cmd_type}' "
                       f"(action={params.get('action')!r}).",
        }

    if not _DATABLOCK_LEASES:
        return None

    if cmd_type == "execute_code":
        return {
            "status": "error",
            "code": "LEASE_VIOLATION",
            "message": "Raw execute_code is blocked while Phase 1 swarm datablock leases are active.",
        }

    if agent_role == "orchestrator":
        return None

    lease_info = _DATABLOCK_LEASES.get(agent_role)
    if not lease_info:
        return {
            "status": "error",
            "code": "LEASE_VIOLATION",
            "message": f"Role '{agent_role}' holds no active datablock lease.",
        }

    prefixes: List[str] = lease_info.get("prefixes", [])
    candidates: List[str] = []
    for key in ("name", "obj_name", "target_name", "material_name", "armature_name"):
        val = params.get(key)
        if isinstance(val, str) and val:
            candidates.append(val)
    for list_key in ("join_objects", "bind_meshes"):
        val_list = params.get(list_key)
        if isinstance(val_list, list):
            for item in val_list:
                if isinstance(item, str) and item:
                    candidates.append(item)
                elif isinstance(item, dict) and item.get("mesh_name"):
                    candidates.append(str(item["mesh_name"]))

    for target in candidates:
        if not any(target.startswith(pfx) for pfx in prefixes):
            return {
                "status": "error",
                "code": "LEASE_VIOLATION",
                "message": f"Role '{agent_role}' lease {prefixes} does not permit modifying '{target}'.",
            }
    return None


@contextlib.contextmanager
def atomic_context_guard(target_obj: Any, mode: str = "EDIT", extra_selected: Optional[List[Any]] = None):
    if bpy is None or target_obj is None or not getattr(bpy, "context", None):
        yield
        return

    view_layer = bpy.context.view_layer
    prev_active_name = view_layer.objects.active.name if view_layer.objects.active else None
    prev_mode = view_layer.objects.active.mode if view_layer.objects.active else "OBJECT"
    prev_selected_names = [o.name for o in bpy.context.selected_objects]

    prev_hide_vp = getattr(target_obj, "hide_viewport", False)
    prev_hide_get = target_obj.hide_get() if hasattr(target_obj, "hide_get") else False

    try:
        if hasattr(target_obj, "hide_viewport"):
            target_obj.hide_viewport = False
        if hasattr(target_obj, "hide_set"):
            target_obj.hide_set(False)

        if view_layer.objects.active and view_layer.objects.active.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")

        bpy.ops.object.select_all(action="DESELECT")
        target_obj.select_set(True)
        if extra_selected:
            for extra in extra_selected:
                if extra is not None and hasattr(extra, "select_set"):
                    extra.select_set(True)
        view_layer.objects.active = target_obj

        if mode != "OBJECT":
            bpy.ops.object.mode_set(mode=mode)
        yield
    finally:
        try:
            if view_layer.objects.active and view_layer.objects.active.mode != "OBJECT":
                bpy.ops.object.mode_set(mode="OBJECT")
            bpy.ops.object.select_all(action="DESELECT")
            if hasattr(target_obj, "name") and target_obj.name in bpy.data.objects:
                if hasattr(target_obj, "hide_viewport"):
                    target_obj.hide_viewport = prev_hide_vp
                if hasattr(target_obj, "hide_set"):
                    target_obj.hide_set(prev_hide_get)
            for s_name in prev_selected_names:
                sobj = bpy.data.objects.get(s_name)
                if sobj and sobj.name in view_layer.objects:
                    sobj.select_set(True)
            if prev_active_name and prev_active_name in view_layer.objects:
                view_layer.objects.active = bpy.data.objects.get(prev_active_name)
                if prev_mode != "OBJECT":
                    bpy.ops.object.mode_set(mode=prev_mode)
        except Exception:
            pass


def kit_checkpoint(
    asset_name: str = "Scene",
    tag: str = "pre_edit",
    keep_last: int = 5,
    agent_role: str = "orchestrator",
) -> Dict[str, Any]:
    session_asset_dir = Path(resolve_session_dir(asset_name))
    chk_dir = session_asset_dir / "checkpoints"
    chk_dir.mkdir(parents=True, exist_ok=True)

    # During active Phase 1 specialist leases, avoid blocking main thread with full disk saves
    if _DATABLOCK_LEASES and agent_role not in ("orchestrator", ""):
        mirror_state_to_blend({"last_subagent_tag": f"{agent_role}:{tag}"})
        return {"checkpoint": "in_memory_mirror", "agent_role": agent_role, "tag": tag, "bytes": 0}

    path = chk_dir / f"{tag}.blend"
    if bpy is not None and hasattr(bpy, "ops") and hasattr(bpy.ops, "wm"):
        bpy.ops.wm.save_as_mainfile(filepath=str(path), copy=True)
    else:
        path.write_bytes(b"MOCK_BLEND_CHECKPOINT")

    # Prune oldest checkpoints beyond keep_last
    all_blends = sorted(chk_dir.glob("*.blend"), key=lambda p: p.stat().st_mtime)
    max_keep = max(1, int(keep_last))
    while len(all_blends) > max_keep:
        oldest = all_blends.pop(0)
        try:
            oldest.unlink()
        except OSError:
            pass

    mirror_state_to_blend({"last_checkpoint": str(path), "asset_name": asset_name})
    return {"checkpoint": str(path), "bytes": path.stat().st_size if path.exists() else 0}


ensure_checkpoint = kit_checkpoint


def kit_session_manage(
    action: str = "init",
    asset_name: str = "Scene",
    target_mode: str = "game_realtime",
    agent_role: str = "orchestrator",
    lease_prefixes: Optional[List[str]] = None,
    keep_last: int = 5,
) -> Dict[str, Any]:
    _prune_expired_leases()
    session_root = Path(resolve_session_dir(None, target_mode=target_mode))
    asset_dir = Path(resolve_session_dir(asset_name, target_mode=target_mode))
    cfg_dir = session_root / "config"

    if action == "init":
        state = mirror_state_to_blend({
            "session_dir": str(session_root),
            "asset_dir": str(asset_dir),
            "config_dir": str(cfg_dir),
            "target_mode": target_mode,
        })
        return {
            "action": "init",
            "session_dir": str(session_root),
            "asset_dir": str(asset_dir),
            "config_dir": str(cfg_dir),
            "target_mode": target_mode,
            "state": state,
        }

    elif action == "acquire_lease":
        prefixes = list(lease_prefixes or [])
        _DATABLOCK_LEASES[agent_role] = {
            "prefixes": prefixes,
            "acquired_at": time.time(),
            "ttl": LEASE_TTL_SECONDS,
        }
        return {"action": "acquire_lease", "agent_role": agent_role, "prefixes": prefixes, "active_leases": list(_DATABLOCK_LEASES.keys())}

    elif action == "release_lease":
        _DATABLOCK_LEASES.pop(agent_role, None)
        return {"action": "release_lease", "agent_role": agent_role, "active_leases": list(_DATABLOCK_LEASES.keys())}

    elif action == "reset_leases":
        _DATABLOCK_LEASES.clear()
        return {"action": "reset_leases", "active_leases": []}

    elif action == "prune_checkpoints":
        chk_dir = asset_dir / "checkpoints"
        removed = 0
        if chk_dir.is_dir():
            blends = sorted(chk_dir.glob("*.blend"), key=lambda p: p.stat().st_mtime)
            while len(blends) > max(1, int(keep_last)):
                old = blends.pop(0)
                try:
                    old.unlink()
                    removed += 1
                except OSError:
                    pass
        return {"action": "prune_checkpoints", "removed": removed, "keep_last": keep_last}

    elif action == "get_state":
        restored = restore_state_from_blend()
        return {
            "action": "get_state",
            "session_dir": str(session_root),
            "asset_dir": str(asset_dir),
            "config_dir": str(cfg_dir),
            "active_leases": {k: v["prefixes"] for k, v in _DATABLOCK_LEASES.items()},
            "blend_state": restored,
        }

    return {"error": f"Unknown session_manage action '{action}'"}

# --- modeling_subd.py ---
"""
Context-free BMesh, Subdivision Surface, Holding Loops, Edge Creases, Modifiers,
Curves, and Transform/Assembly handlers for blender-kit v3.0.
"""
import math
from typing import Any, Dict, List, Optional, Tuple

try:
    import bpy
    import bmesh
    from mathutils import Vector, Matrix, Euler
except ImportError:
    bpy = None
    bmesh = None
    Vector = Matrix = Euler = None


def _get_or_create_collection(collection_name: Optional[str] = None):
    if bpy is None:
        return None
    if collection_name:
        col = bpy.data.collections.get(collection_name)
        if not col:
            col = bpy.data.collections.new(collection_name)
            bpy.context.scene.collection.children.link(col)
        return col
    return bpy.context.scene.collection


def _select_elements_by_rule(bm, elem_type="FACES", selector="all", indices=None, angle_deg=30.0):
    if elem_type == "FACES":
        bm.faces.ensure_lookup_table()
        if indices:
            return [bm.faces[i] for i in indices if 0 <= i < len(bm.faces)]
        if selector == "all":
            return list(bm.faces)
        dirs = {
            "top": Vector((0, 0, 1)),
            "bottom": Vector((0, 0, -1)),
            "front": Vector((0, -1, 0)),
            "back": Vector((0, 1, 0)),
            "right": Vector((1, 0, 0)),
            "left": Vector((-1, 0, 0)),
        }
        if selector in dirs:
            d = dirs[selector]
            return [f for f in bm.faces if f.normal.dot(d) > 0.65]
        return list(bm.faces)

    elif elem_type == "EDGES":
        bm.edges.ensure_lookup_table()
        if indices:
            return [bm.edges[i] for i in indices if 0 <= i < len(bm.edges)]
        if selector == "all":
            return list(bm.edges)
        if selector == "sharp":
            rad = math.radians(float(angle_deg))
            return [e for e in bm.edges if len(e.link_faces) == 2 and e.calc_face_angle(0.0) >= rad]
        if selector == "boundary":
            return [e for e in bm.edges if e.is_boundary]
        if selector == "top":
            zs = [v.co.z for v in bm.verts]
            z_max = max(zs) if zs else 0.0
            return [e for e in bm.edges if all(abs(v.co.z - z_max) < 0.05 for v in e.verts)]
        if selector == "bottom":
            zs = [v.co.z for v in bm.verts]
            z_min = min(zs) if zs else 0.0
            return [e for e in bm.edges if all(abs(v.co.z - z_min) < 0.05 for v in e.verts)]
        if selector == "vertical":
            return [e for e in bm.edges if abs((e.verts[1].co - e.verts[0].co).normalized().z) > 0.85]
        if selector == "horizontal":
            return [e for e in bm.edges if abs((e.verts[1].co - e.verts[0].co).normalized().z) < 0.15]
        return list(bm.edges)


def kit_create_primitive(
    name: str,
    shape: str = "box",
    location: Tuple[float, float, float] = (0.0, 0.0, 0.0),
    rotation_deg: Tuple[float, float, float] = (0.0, 0.0, 0.0),
    size: Tuple[float, float, float] = (1.0, 1.0, 1.0),
    segments: int = 12,
    bevel_width: float = 0.0,
    bevel_segments: int = 1,
    origin_at_bottom: bool = True,
    collection_name: Optional[str] = None,
    parent_name: Optional[str] = None,
    bone_name: Optional[str] = None,
    target_mode: str = "game_realtime",
    smooth_shading: Optional[bool] = None,
) -> Dict[str, Any]:
    bm = bmesh.new()
    sx, sy, sz = float(size[0]), float(size[1]), float(size[2])
    segs = max(3, int(segments))

    if shape == "box":
        bmesh.ops.create_cube(bm, size=1.0)
        bmesh.ops.scale(bm, vec=(sx, sy, sz), verts=bm.verts)
    elif shape == "cylinder":
        bmesh.ops.create_cone(
            bm, cap_ends=True, cap_tris=False, segments=segs,
            radius1=sx * 0.5, radius2=sx * 0.5, depth=sz
        )
        if abs(sx - sy) > 1e-4:
            bmesh.ops.scale(bm, vec=(1.0, sy / max(sx, 1e-5), 1.0), verts=bm.verts)
    elif shape in ("cone", "fang", "spike", "pyramid"):
        segs_use = 4 if shape == "pyramid" else segs
        bmesh.ops.create_cone(
            bm, cap_ends=True, cap_tris=True, segments=segs_use,
            radius1=sx * 0.5, radius2=0.001, depth=sz
        )
        if abs(sx - sy) > 1e-4:
            bmesh.ops.scale(bm, vec=(1.0, sy / max(sx, 1e-5), 1.0), verts=bm.verts)
    elif shape == "sphere":
        bmesh.ops.create_uvsphere(bm, u_segments=segs, v_segments=max(4, segs // 2), radius=0.5)
        bmesh.ops.scale(bm, vec=(sx, sy, sz), verts=bm.verts)
    elif shape == "icosphere":
        bmesh.ops.create_icosphere(bm, subdivisions=min(4, max(1, segs // 4)), radius=0.5)
        bmesh.ops.scale(bm, vec=(sx, sy, sz), verts=bm.verts)
    elif shape == "capsule":
        bmesh.ops.create_uvsphere(bm, u_segments=segs, v_segments=max(6, segs // 2), radius=sx * 0.5)
        half_cyl = max(0.0, (sz - sx) * 0.5)
        for v in bm.verts:
            if v.co.z > 0:
                v.co.z += half_cyl
            elif v.co.z < 0:
                v.co.z -= half_cyl
    elif shape == "torus":
        major_r, minor_r = sx * 0.38, sx * 0.12
        minor_segs = max(4, segs // 2)
        rings = []
        for i in range(segs):
            theta = 2.0 * math.pi * i / segs
            ct, st = math.cos(theta), math.sin(theta)
            ring = []
            for j in range(minor_segs):
                phi = 2.0 * math.pi * j / minor_segs
                r = major_r + minor_r * math.cos(phi)
                z = minor_r * math.sin(phi) * (sz / max(sx, 1e-5))
                ring.append(bm.verts.new((r * ct, r * st, z)))
            rings.append(ring)
        for i in range(segs):
            ni = (i + 1) % segs
            for j in range(minor_segs):
                nj = (j + 1) % minor_segs
                bm.faces.new((rings[i][j], rings[ni][j], rings[ni][nj], rings[i][nj]))
    elif shape == "blade_foil":
        levels = [
            (-sz * 0.5, sx * 0.5, sy * 0.5),
            (sz * 0.15, sx * 0.42, sy * 0.40),
            (sz * 0.38, sx * 0.25, sy * 0.22),
        ]
        rings = []
        for z_val, hw, ht in levels:
            rings.append([
                bm.verts.new((hw, 0.0, z_val)),
                bm.verts.new((0.0, ht, z_val)),
                bm.verts.new((-hw, 0.0, z_val)),
                bm.verts.new((0.0, -ht, z_val)),
            ])
        v_tip = bm.verts.new((0.0, 0.0, sz * 0.5))
        bm.faces.new((rings[0][3], rings[0][2], rings[0][1], rings[0][0]))
        for li in range(len(rings) - 1):
            for k in range(4):
                kn = (k + 1) % 4
                bm.faces.new((rings[li][k], rings[li][kn], rings[li + 1][kn], rings[li + 1][k]))
        for k in range(4):
            kn = (k + 1) % 4
            bm.faces.new((rings[2][k], rings[2][kn], v_tip))
    elif shape == "arch":
        arch_segs = max(6, segs)
        outer_r, inner_r, half_y = sx * 0.5, sx * 0.32, sy * 0.5
        p_fi, p_fo, p_bi, p_bo = [], [], [], []
        for i in range(arch_segs + 1):
            ang = math.pi * i / arch_segs
            ca, sa = math.cos(ang), math.sin(ang)
            p_fi.append(bm.verts.new((inner_r * ca, -half_y, sz * 0.2 + inner_r * sa)))
            p_fo.append(bm.verts.new((outer_r * ca, -half_y, sz * 0.2 + outer_r * sa)))
            p_bi.append(bm.verts.new((inner_r * ca, half_y, sz * 0.2 + inner_r * sa)))
            p_bo.append(bm.verts.new((outer_r * ca, half_y, sz * 0.2 + outer_r * sa)))
        for i in range(arch_segs):
            bm.faces.new((p_fi[i], p_fo[i], p_fo[i + 1], p_fi[i + 1]))
            bm.faces.new((p_bo[i], p_bi[i], p_bi[i + 1], p_bo[i + 1]))
            bm.faces.new((p_fo[i], p_bo[i], p_bo[i + 1], p_fo[i + 1]))
            bm.faces.new((p_bi[i], p_fi[i], p_fi[i + 1], p_bi[i + 1]))
    elif shape == "crystal_shard":
        ring_low, ring_mid = [], []
        for i in range(segs):
            ang = 2.0 * math.pi * i / segs
            ring_low.append(bm.verts.new((math.cos(ang) * sx * 0.35, math.sin(ang) * sy * 0.35, -sz * 0.25)))
            ring_mid.append(bm.verts.new((math.cos(ang) * sx * 0.5, math.sin(ang) * sy * 0.5, sz * 0.1)))
        v_bot = bm.verts.new((0.0, 0.0, -sz * 0.5))
        v_top = bm.verts.new((0.0, 0.0, sz * 0.5))
        for i in range(segs):
            n = (i + 1) % segs
            bm.faces.new((ring_low[n], ring_low[i], v_bot))
            bm.faces.new((ring_low[i], ring_low[n], ring_mid[n], ring_mid[i]))
            bm.faces.new((ring_mid[i], ring_mid[n], v_top))
    elif shape == "starburst_glint":
        points = max(4, int(segments))
        v_front = bm.verts.new((0.0, -sy * 0.12, 0.0))
        v_back = bm.verts.new((0.0, sy * 0.12, 0.0))
        ring = []
        for i in range(points * 2):
            ang = math.pi * i / points
            r = (sx * 0.5) if (i % 2 == 0) else (sx * 0.12)
            ring.append(bm.verts.new((math.cos(ang) * r, 0.0, math.sin(ang) * r)))
        for i in range(points * 2):
            n = (i + 1) % (points * 2)
            bm.faces.new((ring[i], ring[n], v_front))
            bm.faces.new((ring[n], ring[i], v_back))
    else:
        bmesh.ops.create_cube(bm, size=1.0)
        bmesh.ops.scale(bm, vec=(sx, sy, sz), verts=bm.verts)

    if bevel_width > 0.0:
        bmesh.ops.bevel(
            bm, geom=list(bm.edges), offset=float(bevel_width),
            offset_type='OFFSET', segments=max(1, int(bevel_segments)),
            profile=0.5, affect='EDGES', clamp_overlap=True
        )

    if origin_at_bottom and bm.verts:
        min_z = min(v.co.z for v in bm.verts)
        bmesh.ops.translate(bm, vec=(0.0, 0.0, -min_z), verts=bm.verts)

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    mesh = bpy.data.meshes.new(name)
    bm.to_mesh(mesh)
    bm.free()

    use_smooth = (target_mode == "film_cinematic") if smooth_shading is None else bool(smooth_shading)
    for p in mesh.polygons:
        p.use_smooth = use_smooth

    obj = bpy.data.objects.new(name, mesh)
    col = _get_or_create_collection(collection_name)
    col.objects.link(obj)

    obj.location = Vector(location)
    obj.rotation_euler = Euler([math.radians(a) for a in rotation_deg], 'XYZ')

    if parent_name:
        parent = bpy.data.objects.get(parent_name)
        if parent:
            obj.parent = parent
    if bone_name:
        vg = obj.vertex_groups.new(name=bone_name)
        vg.add(list(range(len(mesh.vertices))), 1.0, 'REPLACE')

    return {"object": obj.name, "shape": shape, "verts": len(mesh.vertices), "faces": len(mesh.polygons), "smooth": use_smooth}


mesh_create_part = kit_create_primitive


def kit_bmesh_edit(
    obj_name: str,
    operation: str = "bevel",
    selector: str = "sharp",
    indices: Optional[List[int]] = None,
    offset: float = 0.03,
    segments: int = 1,
    profile: float = 0.5,
    angle_deg: float = 30.0,
    translation: Tuple[float, float, float] = (0.0, 0.0, 0.0),
    along_normal: float = 0.0,
    scale: Tuple[float, float, float] = (1.0, 1.0, 1.0),
    thickness: float = 0.04,
    depth: float = 0.0,
    axis: str = "Z",
    taper_factor: float = 0.0,
    twist_deg: float = 0.0,
    plane_co: Tuple[float, float, float] = (0.0, 0.0, 0.5),
    plane_no: Tuple[float, float, float] = (0.0, 0.0, 1.0),
    clear_inner: bool = False,
    clear_outer: bool = False,
    lathe_profile_pts: Optional[List[List[float]]] = None,
    lathe_steps: int = 16,
    lathe_angle_deg: float = 360.0,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj or obj.type != 'MESH':
        return {"error": f"Mesh object '{obj_name}' not found"}

    mesh = obj.data
    bm = bmesh.new()
    bm.from_mesh(mesh)
    bm.verts.ensure_lookup_table()
    bm.edges.ensure_lookup_table()
    bm.faces.ensure_lookup_table()
    bm.normal_update()

    if operation == "bevel":
        edges = _select_elements_by_rule(bm, "EDGES", selector, indices, angle_deg)
        if edges:
            bmesh.ops.bevel(
                bm, geom=edges, offset=float(offset), offset_type='OFFSET',
                segments=max(1, int(segments)), profile=float(profile),
                affect='EDGES', clamp_overlap=True
            )
    elif operation == "extrude":
        faces = _select_elements_by_rule(bm, "FACES", selector, indices, angle_deg)
        if faces:
            avg_no = Vector((0.0, 0.0, 0.0))
            for f in faces:
                avg_no += f.normal
            if avg_no.length > 1e-5:
                avg_no.normalize()
            res = bmesh.ops.extrude_face_region(bm, geom=faces)
            ext_verts = [e for e in res["geom"] if isinstance(e, bmesh.types.BMVert)]
            bmesh.ops.delete(bm, geom=faces, context='FACES_ONLY')
            move_vec = Vector(translation) + avg_no * float(along_normal)
            if move_vec.length > 1e-6:
                bmesh.ops.translate(bm, vec=move_vec, verts=ext_verts)
            if tuple(scale) != (1.0, 1.0, 1.0) and ext_verts:
                center = sum((v.co for v in ext_verts), Vector((0, 0, 0))) / len(ext_verts)
                for v in ext_verts:
                    rel = v.co - center
                    v.co = center + Vector((rel.x * scale[0], rel.y * scale[1], rel.z * scale[2]))
    elif operation == "inset":
        faces = _select_elements_by_rule(bm, "FACES", selector, indices, angle_deg)
        if faces:
            bmesh.ops.inset_region(
                bm, faces=faces, thickness=float(thickness), depth=float(depth),
                use_boundary=True, use_even_offset=True
            )
    elif operation == "subdivide_edges":
        edges = _select_elements_by_rule(bm, "EDGES", selector, indices, angle_deg)
        if edges:
            bmesh.ops.subdivide_edges(bm, edges=edges, cuts=max(1, int(segments)), use_grid_fill=True)
    elif operation == "bisect":
        geom_all = list(bm.verts) + list(bm.edges) + list(bm.faces)
        res = bmesh.ops.bisect_plane(
            bm, geom=geom_all, dist=0.0001,
            plane_co=Vector(plane_co), plane_no=Vector(plane_no),
            clear_inner=bool(clear_inner), clear_outer=bool(clear_outer)
        )
        cut_edges = [e for e in res["geom_cut"] if isinstance(e, bmesh.types.BMEdge)]
        if cut_edges and (clear_inner or clear_outer):
            bmesh.ops.contextual_create(bm, geom=cut_edges)
    elif operation == "taper_twist":
        ax = {"X": 0, "Y": 1, "Z": 2}.get(axis.upper(), 2)
        coords = [v.co[ax] for v in bm.verts]
        c_min, c_max = (min(coords), max(coords)) if coords else (0.0, 1.0)
        span = max(1e-5, c_max - c_min)
        for v in bm.verts:
            t = (v.co[ax] - c_min) / span
            s_fac = 1.0 + float(taper_factor) * t
            ang = math.radians(float(twist_deg)) * t
            ca, sa = math.cos(ang), math.sin(ang)
            if ax == 2:
                x, y = v.co.x * s_fac, v.co.y * s_fac
                v.co.x, v.co.y = x * ca - y * sa, x * sa + y * ca
            elif ax == 1:
                x, z = v.co.x * s_fac, v.co.z * s_fac
                v.co.x, v.co.z = x * ca - z * sa, x * sa + z * ca
            else:
                y, z = v.co.y * s_fac, v.co.z * s_fac
                v.co.y, v.co.z = y * ca - z * sa, y * sa + z * ca
    elif operation == "spin_lathe":
        bm.clear()
        pts = lathe_profile_pts or [(0.0, 0.0), (0.35, 0.0), (0.45, 0.3), (0.25, 0.7), (0.32, 0.9), (0.0, 0.9)]
        steps = max(4, int(lathe_steps))
        full_circle = abs(float(lathe_angle_deg) - 360.0) < 1e-2
        ring_list = []
        for s in range(steps if full_circle else steps + 1):
            ang = math.radians(float(lathe_angle_deg)) * s / steps
            ca, sa = math.cos(ang), math.sin(ang)
            # Accept 2D (radius, z) or 3D (x, y, z) profile points; radius = first coord, height = last.
            ring_list.append([bm.verts.new((float(p[0]) * ca, float(p[0]) * sa, float(p[-1]))) for p in pts])
        rc = len(ring_list)
        for s in range(steps):
            ns = (s + 1) % rc if full_circle else s + 1
            for pi in range(len(pts) - 1):
                bm.faces.new((ring_list[s][pi], ring_list[ns][pi], ring_list[ns][pi + 1], ring_list[s][pi + 1]))
        bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=0.0005)
    elif operation == "symmetrize":
        bmesh.ops.symmetrize(
            bm,
            input=list(bm.verts) + list(bm.edges) + list(bm.faces),
            direction=f"-{axis.upper()}" if not axis.startswith("-") else axis
        )

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()
    return {"object": obj.name, "operation": operation, "verts": len(mesh.vertices), "faces": len(mesh.polygons)}


def kit_subd_and_loops(
    obj_name: str,
    action: str = "add_holding_loops",
    selector: str = "sharp",
    edge_indices: Optional[List[int]] = None,
    offset: float = 0.02,
    crease_value: float = 1.0,
    bevel_weight: float = 1.0,
    subd_levels: int = 2,
    render_levels: int = 3,
    angle_deg: float = 30.0,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj or obj.type != 'MESH':
        return {"error": f"Mesh object '{obj_name}' not found"}

    if action == "add_holding_loops":
        return kit_bmesh_edit(
            obj_name=obj_name,
            operation="bevel",
            selector=selector,
            indices=edge_indices,
            offset=float(offset),
            segments=2,
            profile=1.0,
            angle_deg=angle_deg,
        )

    elif action == "setup_subsurf":
        for p in obj.data.polygons:
            p.use_smooth = True
        return kit_modifier(
            obj_name=obj_name,
            action="add",
            mod_type="SUBSURF",
            mod_name="KIT_SUBSURF",
            apply_now=False,
            settings={
                "subdivision_type": "CATMULL_CLARK",
                "levels": int(subd_levels),
                "render_levels": int(render_levels),
                "use_creases": True,
                "uv_smooth": "PRESERVE_BOUNDARIES",
            },
        )

    mesh = obj.data
    bm = bmesh.new()
    bm.from_mesh(mesh)
    # Create custom-data layers BEFORE collecting edge references: adding a layer
    # reallocates BMesh element storage and invalidates previously fetched BMEdges.
    layer = None
    if action == "set_crease":
        layer = bm.edges.layers.float.get("crease_edge") or bm.edges.layers.float.new("crease_edge")
    elif action == "set_bevel_weight":
        layer = bm.edges.layers.float.get("bevel_weight_edge") or bm.edges.layers.float.new("bevel_weight_edge")
    bm.edges.ensure_lookup_table()
    edges = _select_elements_by_rule(bm, "EDGES", selector, edge_indices, angle_deg)

    if action == "set_crease":
        val = max(0.0, min(1.0, float(crease_value)))
        for e in edges:
            e[layer] = val
    elif action == "set_bevel_weight":
        val = max(0.0, min(1.0, float(bevel_weight)))
        for e in edges:
            e[layer] = val
    elif action == "bridge_loops":
        if len(edges) >= 2:
            bmesh.ops.bridge_loops(bm, edges=edges)
    elif action == "grid_fill":
        if edges:
            bmesh.ops.grid_fill(bm, edges=edges)

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()
    return {"object": obj.name, "action": action, "edges_affected": len(edges), "faces": len(mesh.polygons)}


def _apply_single_modifier_depsgraph(obj, target_mod) -> int:
    vis_map = {m.name: m.show_viewport for m in obj.modifiers}
    for m in obj.modifiers:
        m.show_viewport = (m.name == target_mod.name)
    bpy.context.view_layer.update()
    depsgraph = bpy.context.evaluated_depsgraph_get()
    eval_obj = obj.evaluated_get(depsgraph)
    new_mesh = bpy.data.meshes.new_from_object(eval_obj)
    new_mesh.name = obj.data.name
    old_mesh = obj.data
    obj.modifiers.remove(target_mod)
    for m in obj.modifiers:
        if m.name in vis_map:
            m.show_viewport = vis_map[m.name]
    obj.data = new_mesh
    if old_mesh.users == 0:
        bpy.data.meshes.remove(old_mesh)
    return len(obj.data.polygons)


def kit_modifier(
    obj_name: str,
    action: str = "add",
    mod_type: str = "BEVEL",
    mod_name: Optional[str] = None,
    apply_now: bool = False,
    settings: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj:
        return {"error": f"Object '{obj_name}' not found"}

    name_use = mod_name or f"KIT_{mod_type}"
    settings = settings or {}

    if action == "add":
        mod = obj.modifiers.get(name_use) or obj.modifiers.new(name=name_use, type=mod_type)
        unknown_settings = []
        for k, v in settings.items():
            if not hasattr(mod, k):
                unknown_settings.append(k)
                continue
            prop = mod.bl_rna.properties.get(k)
            # Any Object pointer (target, object, mirror_object, offset_object, ...) accepts a name.
            if isinstance(v, str) and prop is not None and prop.type == "POINTER":
                ref = bpy.data.objects.get(v)
                if ref is None:
                    return {"error": f"Setting '{k}': object '{v}' not found"}
                v = ref
            setattr(mod, k, v)
        if apply_now:
            faces_cnt = _apply_single_modifier_depsgraph(obj, mod)
            return {"object": obj.name, "modifier": name_use, "type": mod_type, "applied": True,
                    "faces": faces_cnt, "unknown_settings": unknown_settings}
        return {"object": obj.name, "modifier": name_use, "type": mod_type, "applied": False,
                "unknown_settings": unknown_settings}

    elif action == "apply":
        mod = obj.modifiers.get(name_use)
        if not mod:
            return {"error": f"Modifier '{name_use}' not found on {obj.name}"}
        faces_cnt = _apply_single_modifier_depsgraph(obj, mod)
        return {"object": obj.name, "applied": name_use, "faces": faces_cnt}

    elif action == "remove":
        mod = obj.modifiers.get(name_use)
        if mod:
            obj.modifiers.remove(mod)
        return {"object": obj.name, "removed": name_use}

    return {"error": f"Unknown modifier action '{action}'"}


def kit_curve_tube(
    name: str,
    points: List[List[float]],
    bevel_depth: float = 0.05,
    bevel_resolution: int = 2,
    resolution_u: int = 8,
    cyclic: bool = False,
    taper_start: float = 1.0,
    taper_end: float = 1.0,
    convert_to_mesh: bool = True,
    collection_name: Optional[str] = None,
    target_mode: str = "game_realtime",
) -> Dict[str, Any]:
    curve_data = bpy.data.curves.new(name=name, type='CURVE')
    curve_data.dimensions = '3D'
    curve_data.bevel_depth = float(bevel_depth)
    curve_data.bevel_resolution = max(0, int(bevel_resolution))
    curve_data.resolution_u = max(2, int(resolution_u))
    curve_data.use_fill_caps = True

    spline = curve_data.splines.new(type='POLY')
    spline.points.add(len(points) - 1)
    n_pts = max(1, len(points) - 1)
    for i, pt in enumerate(points):
        t = i / n_pts
        spline.points[i].co = (float(pt[0]), float(pt[1]), float(pt[2]), 1.0)
        spline.points[i].radius = float(taper_start * (1.0 - t) + taper_end * t)
    spline.use_cyclic_u = bool(cyclic)

    col = _get_or_create_collection(collection_name)
    obj = bpy.data.objects.new(name, curve_data)
    col.objects.link(obj)

    if convert_to_mesh:
        bpy.context.view_layer.update()
        depsgraph = bpy.context.evaluated_depsgraph_get()
        eval_obj = obj.evaluated_get(depsgraph)
        new_mesh = bpy.data.meshes.new_from_object(eval_obj)
        new_mesh.name = f"{name}_Mesh"
        obj.name = f"{name}__curve_tmp"  # free the requested name for the mesh object
        mesh_obj = bpy.data.objects.new(name, new_mesh)
        mesh_obj.matrix_world = obj.matrix_world.copy()
        col.objects.link(mesh_obj)
        bpy.data.objects.remove(obj, do_unlink=True)
        bpy.data.curves.remove(curve_data)
        use_smooth = (target_mode == "film_cinematic")
        for p in mesh_obj.data.polygons:
            p.use_smooth = use_smooth
        return {"object": mesh_obj.name, "type": "MESH", "verts": len(mesh_obj.data.vertices), "faces": len(mesh_obj.data.polygons)}

    return {"object": obj.name, "type": "CURVE", "points": len(points)}


def kit_transform_and_assemble(
    obj_name: str,
    apply_location: bool = False,
    apply_rotation: bool = True,
    apply_scale: bool = True,
    set_origin: Optional[str] = None,
    join_objects: Optional[List[str]] = None,
    assign_materials: Optional[List[str]] = None,
    target_collection: Optional[str] = None,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj or obj.type != 'MESH':
        return {"error": f"Mesh object '{obj_name}' not found"}

    mesh = obj.data
    bm = bmesh.new()
    bm.from_mesh(mesh)

    # 1. Join additional mesh objects in pure BMesh
    if join_objects:
        inv_target = obj.matrix_world.inverted()
        for src_name in join_objects:
            src_obj = bpy.data.objects.get(src_name)
            if not src_obj or src_obj.type != 'MESH' or src_obj == obj:
                continue
            rel_mat = inv_target @ src_obj.matrix_world
            temp_bm = bmesh.new()
            temp_bm.from_mesh(src_obj.data)
            bmesh.ops.transform(temp_bm, matrix=rel_mat, verts=temp_bm.verts)
            temp_mesh = bpy.data.meshes.new("_tmp_join")
            temp_bm.to_mesh(temp_mesh)
            temp_bm.free()
            bm.from_mesh(temp_mesh)
            bpy.data.meshes.remove(temp_mesh)
            old_src_mesh = src_obj.data
            bpy.data.objects.remove(src_obj, do_unlink=True)
            if old_src_mesh.users == 0:
                bpy.data.meshes.remove(old_src_mesh)

    # 2. Apply scale / rotation / location in pure BMesh
    loc, rot, sca = obj.matrix_world.decompose()
    mat_apply = Matrix.Identity(4)
    if apply_location:
        mat_apply = Matrix.Translation(loc) @ mat_apply
        obj.location = Vector((0.0, 0.0, 0.0))
    if apply_rotation:
        mat_apply = mat_apply @ rot.to_matrix().to_4x4()
        obj.rotation_euler = Euler((0.0, 0.0, 0.0), 'XYZ')
    if apply_scale:
        mat_sca = Matrix.Diagonal((sca.x, sca.y, sca.z, 1.0))
        mat_apply = mat_apply @ mat_sca
        obj.scale = Vector((1.0, 1.0, 1.0))

    if mat_apply != Matrix.Identity(4):
        bmesh.ops.transform(bm, matrix=mat_apply, verts=bm.verts)

    # 3. Set origin ("BOTTOM_CENTER" | "GEOMETRY_CENTER" | "WORLD_ORIGIN")
    if set_origin and bm.verts:
        xs = [v.co.x for v in bm.verts]
        ys = [v.co.y for v in bm.verts]
        zs = [v.co.z for v in bm.verts]
        if set_origin == "BOTTOM_CENTER":
            pivot = Vector((0.5 * (min(xs) + max(xs)), 0.5 * (min(ys) + max(ys)), min(zs)))
            bmesh.ops.translate(bm, vec=-pivot, verts=bm.verts)
            obj.location += pivot
        elif set_origin == "GEOMETRY_CENTER":
            pivot = Vector((0.5 * (min(xs) + max(xs)), 0.5 * (min(ys) + max(ys)), 0.5 * (min(zs) + max(zs))))
            bmesh.ops.translate(bm, vec=-pivot, verts=bm.verts)
            obj.location += pivot
        elif set_origin == "WORLD_ORIGIN":
            bmesh.ops.translate(bm, vec=obj.location, verts=bm.verts)
            obj.location = Vector((0.0, 0.0, 0.0))

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    # 4. Bind material slots
    if assign_materials:
        mesh.materials.clear()
        for mat_name in assign_materials:
            mat = bpy.data.materials.get(mat_name)
            if mat:
                mesh.materials.append(mat)

    # 5. Move to target collection
    if target_collection:
        col = _get_or_create_collection(target_collection)
        if obj.name not in col.objects:
            for c in list(obj.users_collection):
                c.objects.unlink(obj)
            col.objects.link(obj)

    return {"object": obj.name, "verts": len(mesh.vertices), "faces": len(mesh.polygons)}

# --- target_compile.py ---
"""
Dual-Target Compiler (game_realtime, film_cinematic, dual_cage), Double-Shell Stripper,
and Smart Quads-to-Triangles Optimizer for blender-kit v3.0.
Snapshots un-triangulated source quad control cages into .kit_cage_<obj_name> before
game_realtime optimization so cages can be non-destructively restored or re-compiled.
"""
import math
from typing import Any, Dict, List, Optional

try:
    import bpy
    import bmesh
    from mathutils import Vector
except ImportError:
    bpy = None
    bmesh = None
    Vector = None


def kit_clean_and_strip_shells(
    obj_name: str,
    weld_dist: float = 0.0005,
    strip_inner_shells: bool = True,
    shell_ray_dist: float = 0.015,
    flat_shade: bool = True,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj or obj.type != 'MESH':
        return {"error": f"Mesh object '{obj_name}' not found"}

    mesh = obj.data
    orig_verts, orig_faces = len(mesh.vertices), len(mesh.polygons)

    bm = bmesh.new()
    bm.from_mesh(mesh)
    if weld_dist > 0:
        bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=float(weld_dist))
    bm.verts.ensure_lookup_table()
    bm.edges.ensure_lookup_table()
    bm.faces.ensure_lookup_table()
    bm.normal_update()

    stripped_shells = 0
    if strip_inner_shells:
        from mathutils.bvhtree import BVHTree
        bvh = BVHTree.FromBMesh(bm, epsilon=1e-5)
        visited = set()
        comps = []
        for f in bm.faces:
            if f.index in visited:
                continue
            comp = []
            q = [f]
            visited.add(f.index)
            while q:
                curr = q.pop()
                comp.append(curr)
                for e in curr.edges:
                    for nf in e.link_faces:
                        if nf.index not in visited:
                            visited.add(nf.index)
                            q.append(nf)
            comps.append(comp)

        del_faces = []
        for comp in comps:
            if len(comp) > 60 or len(comp) < 4:
                continue
            comp_indices = {f.index for f in comp}
            buried_count = 0
            for f in comp:
                no = f.normal
                if no.length < 1e-6:
                    continue
                origin = f.calc_center_median() + no * 0.0006
                loc, norm, idx, dist = bvh.ray_cast(origin, no, shell_ray_dist)
                if loc is not None and idx not in comp_indices:
                    buried_count += 1
            if buried_count >= len(comp) * 0.55:
                del_faces.extend(comp)
                stripped_shells += 1

        if del_faces:
            bmesh.ops.delete(bm, geom=del_faces, context='FACES')

    degen = [f for f in bm.faces if f.calc_area() < 1e-7]
    if degen:
        bmesh.ops.delete(bm, geom=degen, context='FACES')

    loose_v = [v for v in bm.verts if not v.link_faces]
    if loose_v:
        bmesh.ops.delete(bm, geom=loose_v, context='VERTS')

    bm.to_mesh(mesh)
    bm.free()

    if "custom_normal" in mesh.attributes:
        mesh.attributes.remove(mesh.attributes["custom_normal"])

    for p in mesh.polygons:
        p.use_smooth = not bool(flat_shade)

    mesh.update()
    return {
        "object": obj.name,
        "orig_verts": orig_verts,
        "orig_faces": orig_faces,
        "verts": len(mesh.vertices),
        "faces": len(mesh.polygons),
        "stripped_inner_shells": stripped_shells,
    }


mesh_clean_and_strip_shells = kit_clean_and_strip_shells


def _resolve_joint_positions(obj, joint_landmarks: Optional[List[List[float]]] = None) -> List[Any]:
    joint_positions = []
    if joint_landmarks:
        inv_obj = obj.matrix_world.inverted()
        for pt in joint_landmarks:
            joint_positions.append(inv_obj @ Vector((float(pt[0]), float(pt[1]), float(pt[2]))))
        return joint_positions

    arm = None
    if obj.parent and obj.parent.type == 'ARMATURE':
        arm = obj.parent
    else:
        for mod in obj.modifiers:
            if mod.type == 'ARMATURE' and getattr(mod, "object", None):
                arm = mod.object
                break

    if arm is not None:
        mat_to_obj = obj.matrix_world.inverted() @ arm.matrix_world
        for bone in arm.data.bones:
            if bone.parent:
                joint_positions.append(mat_to_obj @ bone.head_local)
    return joint_positions


def kit_optimize_quads_to_tris(
    obj_name: str,
    planar_angle_deg: float = 2.5,
    preserve_joint_quads: bool = True,
    joint_radius: float = 0.18,
    triangulate_static: bool = True,
    joint_landmarks: Optional[List[List[float]]] = None,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj or obj.type != 'MESH':
        return {"error": f"Mesh object '{obj_name}' not found"}

    mesh = obj.data
    bm = bmesh.new()
    bm.from_mesh(mesh)
    bm.verts.ensure_lookup_table()
    bm.edges.ensure_lookup_table()
    bm.faces.ensure_lookup_table()

    joint_positions = _resolve_joint_positions(obj, joint_landmarks) if preserve_joint_quads else []

    def in_joint_zone(co):
        return any((co - jp).length <= joint_radius for jp in joint_positions)

    if planar_angle_deg > 0:
        rad_limit = math.radians(planar_angle_deg)
        dissolve_edges = []
        for e in bm.edges:
            if len(e.link_faces) == 2 and not e.seam and e.smooth:
                if in_joint_zone(e.verts[0].co) or in_joint_zone(e.verts[1].co):
                    continue
                if e.calc_face_angle(999.0) < rad_limit:
                    dissolve_edges.append(e)
        if dissolve_edges:
            bmesh.ops.dissolve_edges(bm, edges=dissolve_edges, use_verts=True, use_face_split=False)

    bm.faces.ensure_lookup_table()
    ngons = [f for f in bm.faces if len(f.verts) > 4]
    if ngons:
        bmesh.ops.triangulate(bm, faces=ngons, quad_method='BEAUTY', ngon_method='BEAUTY')

    if triangulate_static:
        bm.faces.ensure_lookup_table()
        static_quads = [
            f for f in bm.faces
            if len(f.verts) == 4 and not in_joint_zone(f.calc_center_median())
        ]
        if static_quads:
            bmesh.ops.triangulate(bm, faces=static_quads, quad_method='BEAUTY', ngon_method='BEAUTY')

    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    quads = sum(1 for p in mesh.polygons if len(p.vertices) == 4)
    tris = sum(1 for p in mesh.polygons if len(p.vertices) == 3)
    ngon_cnt = sum(1 for p in mesh.polygons if len(p.vertices) > 4)
    total_tris = sum(len(p.vertices) - 2 for p in mesh.polygons)

    return {
        "object": obj.name,
        "quads": quads,
        "tris": tris,
        "ngons": ngon_cnt,
        "total_triangles": total_tris,
    }


topo_optimize_quads_to_tris = kit_optimize_quads_to_tris


def _backup_or_restore_quad_cage(obj, restore: bool = False) -> str:
    cage_name = f".kit_cage_{obj.name}"
    existing_cage = bpy.data.meshes.get(cage_name)
    if restore and existing_cage is not None:
        old_mesh = obj.data
        obj.data = existing_cage.copy()
        obj.data.name = f"{obj.name}_Mesh"
        if old_mesh.users == 0 and old_mesh != existing_cage:
            bpy.data.meshes.remove(old_mesh)
        return cage_name

    if existing_cage is None:
        backup = obj.data.copy()
        backup.name = cage_name
        backup.use_fake_user = True
    return cage_name


def kit_compile_target(
    obj_name: str,
    target_mode: str = "game_realtime",
    tri_budget: int = 2500,
    subd_levels: int = 2,
    render_levels: int = 3,
    preserve_joint_quads: bool = True,
    joint_radius: float = 0.18,
    joint_landmarks: Optional[List[List[float]]] = None,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj or obj.type != 'MESH':
        return {"error": f"Mesh object '{obj_name}' not found"}

    if target_mode == "film_cinematic":
        _backup_or_restore_quad_cage(obj, restore=True)
        for p in obj.data.polygons:
            p.use_smooth = True

        # Add weight-driven holding-loop bevel + Catmull-Clark SUBSURF if not present
        bev = obj.modifiers.get("KIT_SUBD_BEVEL") or obj.modifiers.new(name="KIT_SUBD_BEVEL", type="BEVEL")
        bev.limit_method = 'WEIGHT'
        bev.segments = 2
        bev.profile = 1.0
        bev.use_clamp_overlap = True

        sub = obj.modifiers.get("KIT_SUBSURF") or obj.modifiers.new(name="KIT_SUBSURF", type="SUBSURF")
        sub.subdivision_type = 'CATMULL_CLARK'
        sub.levels = int(subd_levels)
        sub.render_levels = int(render_levels)
        sub.use_creases = True
        if hasattr(sub, "uv_smooth"):
            sub.uv_smooth = 'PRESERVE_BOUNDARIES'

        quads = sum(1 for p in obj.data.polygons if len(p.vertices) == 4)
        tris = sum(1 for p in obj.data.polygons if len(p.vertices) == 3)
        ngons = sum(1 for p in obj.data.polygons if len(p.vertices) > 4)
        return {
            "object": obj.name,
            "target_mode": "film_cinematic",
            "cage_quads": quads,
            "cage_tris": tris,
            "cage_ngons": ngons,
            "subd_levels": subd_levels,
            "pass": ngons == 0,
        }

    elif target_mode == "game_realtime":
        cage_name = _backup_or_restore_quad_cage(obj, restore=True)
        for m in list(obj.modifiers):
            if m.type in ("SUBSURF", "BEVEL") and m.name.startswith("KIT_"):
                obj.modifiers.remove(m)

        clean_res = kit_clean_and_strip_shells(obj.name, flat_shade=True)
        opt_res = kit_optimize_quads_to_tris(
            obj.name,
            planar_angle_deg=2.5,
            preserve_joint_quads=preserve_joint_quads,
            joint_radius=joint_radius,
            triangulate_static=True,
            joint_landmarks=joint_landmarks,
        )
        total_tris = opt_res["total_triangles"]
        budget_ok = (tri_budget <= 0) or (total_tris <= tri_budget)
        return {
            "object": obj.name,
            "target_mode": "game_realtime",
            "backup_cage": cage_name,
            "stripped_inner_shells": clean_res["stripped_inner_shells"],
            "quads": opt_res["quads"],
            "tris": opt_res["tris"],
            "ngons": opt_res["ngons"],
            "total_triangles": total_tris,
            "tri_budget": tri_budget,
            "pass": opt_res["ngons"] == 0 and budget_ok,
        }

    elif target_mode == "dual_cage":
        base_stem = obj.name.removesuffix("_HP").removesuffix("_LP")
        hp_name = f"{base_stem}_HP"
        lp_name = f"{base_stem}_LP"

        hp_obj = bpy.data.objects.get(hp_name)
        if not hp_obj:
            hp_mesh = obj.data.copy()
            hp_mesh.name = f"{hp_name}_Mesh"
            hp_obj = bpy.data.objects.new(hp_name, hp_mesh)
            hp_obj.matrix_world = obj.matrix_world.copy()
            for c in obj.users_collection:
                c.objects.link(hp_obj)

        lp_obj = bpy.data.objects.get(lp_name)
        if not lp_obj:
            lp_mesh = obj.data.copy()
            lp_mesh.name = f"{lp_name}_Mesh"
            lp_obj = bpy.data.objects.new(lp_name, lp_mesh)
            lp_obj.matrix_world = obj.matrix_world.copy()
            for c in obj.users_collection:
                c.objects.link(lp_obj)

        hp_res = kit_compile_target(hp_obj.name, target_mode="film_cinematic", subd_levels=subd_levels, render_levels=render_levels)
        lp_res = kit_compile_target(
            lp_obj.name,
            target_mode="game_realtime",
            tri_budget=tri_budget,
            preserve_joint_quads=preserve_joint_quads,
            joint_radius=joint_radius,
            joint_landmarks=joint_landmarks,
        )
        return {
            "target_mode": "dual_cage",
            "hp": hp_res,
            "lp": lp_res,
            "pass": hp_res.get("pass", False) and lp_res.get("pass", False),
        }

    return {"error": f"Unknown target_mode '{target_mode}'"}

# --- node_graphs.py ---
"""
Declarative Shader, Geometry Nodes & Compositor DAG Builder, Context-Guarded UV Unwrap,
Material Presets, and Gleam/Shimmer VFX Handlers for blender-kit v3.0.
"""
import math
from typing import Any, Dict, List, Optional, Tuple

try:
    import bpy
    import bmesh
    from mathutils import Vector
except ImportError:
    bpy = None
    bmesh = None
    Vector = None


_SOCKET_ALIASES = {
    "base_color": ["Base Color", "Color"],
    "subsurface": ["Subsurface Weight", "Subsurface"],
    "metallic": ["Metallic"],
    "specular": ["Specular IOR Level", "Specular"],
    "roughness": ["Roughness"],
    "transmission": ["Transmission Weight", "Transmission"],
    "coat": ["Coat Weight", "Clearcoat"],
    "emission": ["Emission Color", "Emission"],
    "emission_strength": ["Emission Strength"],
    "alpha": ["Alpha"],
    "normal": ["Normal"],
}


def _resolve_socket(sockets, name_or_alias: str):
    if name_or_alias in sockets:
        return sockets[name_or_alias]
    key = name_or_alias.strip().lower().replace(" ", "_")
    for candidate in _SOCKET_ALIASES.get(key, []):
        if candidate in sockets:
            return sockets[candidate]
    for s in sockets:
        if s.name.lower() == name_or_alias.strip().lower():
            return s
    return None


def kit_uv_unwrap(
    obj_name: str,
    method: str = "auto_seams",
    seam_angle_deg: float = 55.0,
    island_margin: float = 0.02,
    texture_size: int = 1024,
    target_density_px_per_m: float = 256.0,
    scale_to_target_density: bool = False,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name)
    if not obj or obj.type != 'MESH':
        return {"error": f"Mesh object '{obj_name}' not found"}

    mesh = obj.data
    if not mesh.uv_layers:
        mesh.uv_layers.new(name="UVMap")

    bm = bmesh.new()
    bm.from_mesh(mesh)
    bm.faces.ensure_lookup_table()
    bm.edges.ensure_lookup_table()
    uv_lay = bm.loops.layers.uv.active or bm.loops.layers.uv.new("UVMap")

    seams_marked = 0
    if method == "zero_bleed_facet_atlas":
        n_faces = max(1, len(bm.faces))
        grid = max(1, math.ceil(math.sqrt(n_faces)))
        cell_size = 1.0 / grid
        pad_uv = max(6.0 / max(64, int(texture_size)), cell_size * 0.12)
        inner = max(1e-4, cell_size - 2.0 * pad_uv)
        for idx, f in enumerate(bm.faces):
            gx = idx % grid
            gy = idx // grid
            u0 = gx * cell_size + pad_uv
            v0 = gy * cell_size + pad_uv
            n_l = max(1, len(f.loops))
            for li, loop in enumerate(f.loops):
                ang = (2.0 * math.pi * li) / n_l
                loop[uv_lay].uv = (
                    u0 + inner * (0.5 + 0.45 * math.cos(ang)),
                    v0 + inner * (0.5 + 0.45 * math.sin(ang)),
                )
        bm.to_mesh(mesh)
        bm.free()
    else:
        rad = math.radians(float(seam_angle_deg))
        for e in bm.edges:
            if e.is_boundary or (len(e.link_faces) == 2 and e.calc_face_angle(0.0) >= rad):
                e.seam = True
                seams_marked += 1
        bm.to_mesh(mesh)
        bm.free()

        with atomic_context_guard(obj, mode="EDIT"):
            bpy.ops.mesh.select_all(action='SELECT')
            if method == "smart_project":
                bpy.ops.uv.smart_project(angle_limit=math.radians(float(seam_angle_deg)), island_margin=float(island_margin))
            elif method == "cube_project":
                bpy.ops.uv.cube_project(cube_size=1.0)
            elif method == "cylinder_project":
                bpy.ops.uv.cylinder_project(scale_to_bounds=True)
            elif method == "sphere_project":
                bpy.ops.uv.sphere_project(scale_to_bounds=True)
            elif method == "conformal":
                bpy.ops.uv.unwrap(method='CONFORMAL', margin=float(island_margin))
            else:
                bpy.ops.uv.unwrap(method='ANGLE_BASED', margin=float(island_margin))
            bpy.ops.uv.pack_islands(margin=float(island_margin), rotate=True)

    # Measure UV coverage, bounds, and texel density
    bm_m = bmesh.new()
    bm_m.from_mesh(mesh)
    uv_m = bm_m.loops.layers.uv.active
    s = obj.matrix_world.to_scale()
    scale_factor = abs(s.x * s.y * s.z) ** (2.0 / 3.0) if (s.x and s.y and s.z) else 1.0
    world_area = 0.0
    uv_area = 0.0
    out_of_bounds = 0
    if uv_m is not None:
        for f in bm_m.faces:
            world_area += f.calc_area() * scale_factor
            pts = [l[uv_m].uv.copy() for l in f.loops]
            for p in pts:
                if p.x < -1e-3 or p.x > 1.001 or p.y < -1e-3 or p.y > 1.001:
                    out_of_bounds += 1
            a = 0.0
            for i in range(len(pts)):
                x1, y1 = pts[i]
                x2, y2 = pts[(i + 1) % len(pts)]
                a += x1 * y2 - x2 * y1
            uv_area += abs(a) * 0.5

        measured_density = float(texture_size) * math.sqrt(uv_area / world_area) if (world_area > 0 and uv_area > 0) else 0.0
        if scale_to_target_density and measured_density > 1e-4 and target_density_px_per_m > 0:
            ratio = float(target_density_px_per_m) / measured_density
            for f in bm_m.faces:
                for l in f.loops:
                    u, v = l[uv_m].uv
                    l[uv_m].uv = (0.5 + (u - 0.5) * ratio, 0.5 + (v - 0.5) * ratio)
            bm_m.to_mesh(mesh)
            uv_area *= ratio * ratio
            measured_density = float(target_density_px_per_m)
    else:
        measured_density = 0.0
    bm_m.free()

    return {
        "object": obj.name,
        "method": method,
        "seams_marked": seams_marked,
        "uv_layer": mesh.uv_layers.active.name if mesh.uv_layers.active else "UVMap",
        "texture_size": texture_size,
        "target_density_px_per_m": target_density_px_per_m,
        "measured_texel_density_px_per_m": round(measured_density, 2),
        "uv_area_sum": round(uv_area, 4),
        "world_area_m2": round(world_area, 4),
        "out_of_bounds_uvs": out_of_bounds,
    }


def kit_material_preset(
    obj_name: Optional[str] = None,
    preset: str = "stylized_pbr",
    base_color: Tuple[float, float, float] = (0.75, 0.25, 0.22),
    secondary_color: Tuple[float, float, float] = (0.92, 0.78, 0.65),
    roughness: float = 0.65,
    metallic: float = 0.0,
    emission_strength: float = 0.0,
    material_name: Optional[str] = None,
    bake_to_texture: bool = False,
    texture_size: int = 1024,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name) if obj_name else None
    if obj_name and (not obj or obj.type != 'MESH'):
        return {"error": f"Mesh object '{obj_name}' not found"}

    mat_name = material_name or (f"MAT_{obj.name}_{preset}" if obj else f"MAT_{preset}")
    mat = bpy.data.materials.get(mat_name) or bpy.data.materials.new(name=mat_name)
    mat.use_nodes = True
    nt = mat.node_tree
    nt.nodes.clear()

    out_node = nt.nodes.new("ShaderNodeOutputMaterial")
    bsdf = nt.nodes.new("ShaderNodeBsdfPrincipled")
    nt.links.new(bsdf.outputs["BSDF"], out_node.inputs["Surface"])

    presets = {
        "metal_steel": {"col": (0.68, 0.71, 0.75), "rough": 0.28, "metal": 0.95},
        "gold_trim": {"col": (0.94, 0.76, 0.32), "rough": 0.22, "metal": 0.95},
        "wood_warm": {"col": (0.45, 0.26, 0.14), "rough": 0.78, "metal": 0.0},
        "stone_slate": {"col": (0.38, 0.40, 0.43), "rough": 0.88, "metal": 0.0},
        "crystal_glow": {"col": base_color, "rough": 0.15, "metal": 0.1, "emit": max(2.0, float(emission_strength))},
        "foliage_leaf": {"col": (0.22, 0.58, 0.24), "rough": 0.72, "metal": 0.0},
    }
    cfg = presets.get(preset, {"col": base_color, "rough": roughness, "metal": metallic, "emit": emission_strength})

    _resolve_socket(bsdf.inputs, "base_color").default_value = (*cfg["col"][:3], 1.0)
    _resolve_socket(bsdf.inputs, "roughness").default_value = float(cfg["rough"])
    _resolve_socket(bsdf.inputs, "metallic").default_value = float(cfg["metal"])
    if cfg.get("emit", 0.0) > 0.0:
        em_col = _resolve_socket(bsdf.inputs, "emission")
        if em_col:
            em_col.default_value = (*cfg["col"][:3], 1.0)
        em_str = _resolve_socket(bsdf.inputs, "emission_strength")
        if em_str:
            em_str.default_value = float(cfg["emit"])

    if obj is not None:
        if not obj.data.materials:
            obj.data.materials.append(mat)
        else:
            obj.data.materials[0] = mat

    return {
        "object": obj.name if obj else None,
        "material": mat.name,
        "preset": preset,
        "bake_to_texture": bake_to_texture,
        "texture_size": texture_size,
    }


def kit_add_gleam_effect(
    obj_name: Optional[str] = None,
    mode: str = "shader_sweep",
    gleam_color: Tuple[float, float, float] = (0.85, 0.98, 1.0),
    strength: float = 3.5,
    frame_start: int = 1,
    frame_end: int = 60,
    material_name: Optional[str] = None,
) -> Dict[str, Any]:
    obj = bpy.data.objects.get(obj_name) if obj_name else None
    if mode == "shader_sweep":
        if material_name:
            mat = bpy.data.materials.get(material_name) or bpy.data.materials.new(name=material_name)
            mat.use_nodes = True
        elif obj is not None:
            if not obj.data.materials:
                mat = bpy.data.materials.new(name=f"MAT_{obj.name}_Gleam")
                mat.use_nodes = True
                obj.data.materials.append(mat)
            else:
                mat = obj.data.materials[0]
                mat.use_nodes = True
        else:
            return {"error": "Either obj_name or material_name must be provided for shader_sweep"}

        nt = mat.node_tree
        bsdf = next((n for n in nt.nodes if n.type == 'BSDF_PRINCIPLED'), None)
        if not bsdf:
            bsdf = nt.nodes.new("ShaderNodeBsdfPrincipled")

        tex_coord = nt.nodes.new("ShaderNodeTexCoord")
        mapping = nt.nodes.new("ShaderNodeMapping")
        mapping.name = "GleamSweepMapping"
        mapping.inputs["Rotation"].default_value = (0.0, math.radians(35.0), math.radians(25.0))

        sep_xyz = nt.nodes.new("ShaderNodeSeparateXYZ")
        ramp = nt.nodes.new("ShaderNodeValToRGB")
        ramp.color_ramp.interpolation = 'EASE'
        ramp.color_ramp.elements[0].position = 0.42
        ramp.color_ramp.elements[0].color = (0.0, 0.0, 0.0, 1.0)
        mid_el = ramp.color_ramp.elements.new(0.50)
        mid_el.color = (gleam_color[0], gleam_color[1], gleam_color[2], 1.0)
        ramp.color_ramp.elements[1].position = 0.58
        ramp.color_ramp.elements[1].color = (0.0, 0.0, 0.0, 1.0)

        nt.links.new(tex_coord.outputs["Generated"], mapping.inputs["Vector"])
        nt.links.new(mapping.outputs["Vector"], sep_xyz.inputs["Vector"])
        nt.links.new(sep_xyz.outputs["X"], ramp.inputs["Fac"])

        em_col_sock = _resolve_socket(bsdf.inputs, "emission")
        em_str_sock = _resolve_socket(bsdf.inputs, "emission_strength")
        if em_col_sock:
            nt.links.new(ramp.outputs["Color"], em_col_sock)
        if em_str_sock:
            em_str_sock.default_value = float(strength)

        mapping.inputs["Location"].default_value = (-1.2, 0.0, 0.0)
        mapping.inputs["Location"].keyframe_insert(data_path="default_value", frame=int(frame_start))
        mapping.inputs["Location"].default_value = (1.2, 0.0, 0.0)
        mapping.inputs["Location"].keyframe_insert(data_path="default_value", frame=int(frame_end))

        return {"object": obj.name if obj else None, "material": mat.name, "mode": "shader_sweep", "frames": [frame_start, frame_end]}

    elif mode == "starburst_mesh":
        base_loc = tuple(obj.location + Vector((0.0, -0.5, 0.8))) if obj else (0.0, -0.5, 0.8)
        star_prefix = obj.name if obj else (material_name or "Scene")
        res = kit_create_primitive(
            name=f"FX_{star_prefix}_GleamStar",
            shape="starburst_glint",
            location=base_loc,
            size=(0.45, 0.15, 0.45),
            segments=4,
            parent_name=obj.name if obj else None,
        )
        star_obj = bpy.data.objects.get(res["object"])
        mat = bpy.data.materials.new(name=f"MAT_{star_obj.name}")
        mat.use_nodes = True
        bsdf = next((n for n in mat.node_tree.nodes if n.type == 'BSDF_PRINCIPLED'), None)
        if bsdf:
            _resolve_socket(bsdf.inputs, "base_color").default_value = (*gleam_color, 1.0)
            em_col = _resolve_socket(bsdf.inputs, "emission")
            if em_col:
                em_col.default_value = (*gleam_color, 1.0)
            em_str = _resolve_socket(bsdf.inputs, "emission_strength")
            if em_str:
                em_str.default_value = float(strength) * 1.5
        star_obj.data.materials.append(mat)

        mid_f = (int(frame_start) + int(frame_end)) // 2
        star_obj.scale = (0.01, 0.01, 0.01)
        star_obj.keyframe_insert(data_path="scale", frame=int(frame_start))
        star_obj.scale = (1.0, 1.0, 1.0)
        star_obj.rotation_euler = (0.0, math.radians(90.0), 0.0)
        star_obj.keyframe_insert(data_path="scale", frame=mid_f)
        star_obj.keyframe_insert(data_path="rotation_euler", frame=mid_f)
        star_obj.scale = (0.01, 0.01, 0.01)
        star_obj.rotation_euler = (0.0, math.radians(180.0), 0.0)
        star_obj.keyframe_insert(data_path="scale", frame=int(frame_end))
        star_obj.keyframe_insert(data_path="rotation_euler", frame=int(frame_end))
        return {"object": star_obj.name, "mode": "starburst_mesh", "frames": [frame_start, mid_f, frame_end]}

    return {"error": f"Unknown gleam mode '{mode}'"}


surface_add_gleam_effect = kit_add_gleam_effect


def _expand_macro_preset(macro: str) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    if macro == "triplanar_pbr":
        return (
            [
                {"id": "coord", "type": "ShaderNodeTexCoord"},
                {"id": "noise", "type": "ShaderNodeTexNoise", "inputs": {"Scale": 12.0, "Detail": 6.0}},
                {"id": "ramp", "type": "ShaderNodeValToRGB"},
                {"id": "bump", "type": "ShaderNodeBump", "inputs": {"Strength": 0.15}},
                {"id": "bsdf", "type": "ShaderNodeBsdfPrincipled", "inputs": {"roughness": 0.55}},
                {"id": "out", "type": "ShaderNodeOutputMaterial"},
            ],
            [
                {"from_node": "coord", "from_socket": "Object", "to_node": "noise", "to_socket": "Vector"},
                {"from_node": "noise", "from_socket": "Fac", "to_node": "ramp", "to_socket": "Fac"},
                {"from_node": "ramp", "from_socket": "Color", "to_node": "bsdf", "to_socket": "base_color"},
                {"from_node": "noise", "from_socket": "Fac", "to_node": "bump", "to_socket": "Height"},
                {"from_node": "bump", "from_socket": "Normal", "to_node": "bsdf", "to_socket": "normal"},
                {"from_node": "bsdf", "from_socket": "BSDF", "to_node": "out", "to_socket": "Surface"},
            ],
        )
    elif macro == "edge_cavity_wear":
        return (
            [
                {"id": "geom", "type": "ShaderNodeNewGeometry"},
                {"id": "ramp", "type": "ShaderNodeValToRGB"},
                {"id": "bsdf", "type": "ShaderNodeBsdfPrincipled", "inputs": {"metallic": 0.85, "roughness": 0.35}},
                {"id": "out", "type": "ShaderNodeOutputMaterial"},
            ],
            [
                {"from_node": "geom", "from_socket": "Pointiness", "to_node": "ramp", "to_socket": "Fac"},
                {"from_node": "ramp", "from_socket": "Color", "to_node": "bsdf", "to_socket": "base_color"},
                {"from_node": "bsdf", "from_socket": "BSDF", "to_node": "out", "to_socket": "Surface"},
            ],
        )
    elif macro == "subd_micro_displacement":
        return (
            [
                {"id": "voronoi", "type": "ShaderNodeTexVoronoi", "inputs": {"Scale": 24.0}},
                {"id": "disp", "type": "ShaderNodeDisplacement", "inputs": {"Scale": 0.04}},
                {"id": "bsdf", "type": "ShaderNodeBsdfPrincipled"},
                {"id": "out", "type": "ShaderNodeOutputMaterial"},
            ],
            [
                {"from_node": "voronoi", "from_socket": "Distance", "to_node": "disp", "to_socket": "Height"},
                {"from_node": "bsdf", "from_socket": "BSDF", "to_node": "out", "to_socket": "Surface"},
                {"from_node": "disp", "from_socket": "Displacement", "to_node": "out", "to_socket": "Displacement"},
            ],
        )
    elif macro in ("gn_surface_scatter", "gn_curve_profile_sweep"):
        return (
            [
                {"id": "in", "type": "NodeGroupInput"},
                {"id": "out", "type": "NodeGroupOutput"},
            ],
            [
                {"from_node": "in", "from_socket": "Geometry", "to_node": "out", "to_socket": "Geometry"},
            ],
        )
    elif macro == "comp_cinematic_glare_grade":
        return (
            [
                {"id": "rl", "type": "CompositorNodeRLayers"},
                {"id": "glare", "type": "CompositorNodeGlare", "properties": {"glare_type": "FOG_GLOW", "quality": "HIGH"}},
                {"id": "comp", "type": "CompositorNodeComposite"},
            ],
            [
                {"from_node": "rl", "from_socket": "Image", "to_node": "glare", "to_socket": "Image"},
                {"from_node": "glare", "from_socket": "Image", "to_node": "comp", "to_socket": "Image"},
            ],
        )
    return ([], [])


def kit_node_graph_build(
    tree_type: str = "SHADER",
    target_name: str = "MAT_Default",
    nodes: Optional[List[Dict[str, Any]]] = None,
    links: Optional[List[Dict[str, Any]]] = None,
    interface_sockets: Optional[List[Dict[str, Any]]] = None,
    macro: Optional[str] = None,
    clear_existing: bool = True,
) -> Dict[str, Any]:
    ttype = tree_type.upper()
    if macro:
        m_nodes, m_links = _expand_macro_preset(macro)
        nodes = m_nodes if not nodes else nodes
        links = m_links if not links else links

    nodes = nodes or []
    links = links or []

    # 1. Resolve or create target NodeTree
    if ttype == "SHADER":
        mat = bpy.data.materials.get(target_name) or bpy.data.materials.new(name=target_name)
        mat.use_nodes = True
        nt = mat.node_tree
    elif ttype == "GEOMETRY":
        nt = bpy.data.node_groups.get(target_name) or bpy.data.node_groups.new(name=target_name, type='GeometryNodeTree')
        if hasattr(nt, "interface"):
            existing_names = {item.name for item in nt.interface.items_tree}
            if "Geometry" not in existing_names:
                nt.interface.new_socket(name="Geometry", in_out='INPUT', socket_type='NodeSocketGeometry')
                nt.interface.new_socket(name="Geometry", in_out='OUTPUT', socket_type='NodeSocketGeometry')
            for isock in (interface_sockets or []):
                nt.interface.new_socket(
                    name=isock["name"],
                    in_out=isock.get("in_out", "INPUT").upper(),
                    socket_type=isock.get("socket_type", "NodeSocketFloat"),
                )
        obj = bpy.data.objects.get(target_name)
        if obj and obj.type == 'MESH':
            mod = obj.modifiers.get("KIT_GEONODES") or obj.modifiers.new(name="KIT_GEONODES", type="NODES")
            mod.node_group = nt
    elif ttype == "COMPOSITOR":
        scene = bpy.data.scenes.get(target_name) or bpy.context.scene
        if hasattr(scene, "compositing_node_group"):
            # Blender 5.x: compositor is a CompositorNodeTree node group with an Image output.
            nt = scene.compositing_node_group
            if nt is None:
                nt = bpy.data.node_groups.new(name=f"KIT_Compositor_{scene.name}", type="CompositorNodeTree")
                scene.compositing_node_group = nt
            if not any(i.item_type == "SOCKET" and i.in_out == "OUTPUT" and i.name == "Image"
                       for i in nt.interface.items_tree):
                nt.interface.new_socket(name="Image", in_out="OUTPUT", socket_type="NodeSocketColor")
        else:
            scene.use_nodes = True
            nt = scene.node_tree
    else:
        return {"error": f"Unsupported tree_type '{tree_type}'"}

    if clear_existing:
        nt.nodes.clear()

    created_nodes: Dict[str, Any] = {}
    for nspec in nodes:
        nid = nspec["id"]
        ntype = nspec["type"]
        if ntype == "CompositorNodeComposite" and ttype == "COMPOSITOR" and not hasattr(bpy.types, "CompositorNodeComposite"):
            ntype = "NodeGroupOutput"  # Blender 5.x replacement for the Composite output node
        try:
            node = nt.nodes.new(ntype)
        except Exception as exc:
            return {"error": f"Invalid node type '{ntype}' in {ttype} tree: {exc}"}
        node.name = nid
        if "label" in nspec:
            node.label = str(nspec["label"])
        if "location" in nspec and len(nspec["location"]) >= 2:
            node.location = (float(nspec["location"][0]), float(nspec["location"][1]))
        for prop_k, prop_v in (nspec.get("properties") or {}).items():
            if hasattr(node, prop_k):
                setattr(node, prop_k, prop_v)
                continue
            # Blender 5.x moved many node enums to MENU input sockets (e.g. Glare 'glare_type' -> 'Type').
            sock_name = prop_k.split("_")[-1].title() if prop_k.endswith("_type") else prop_k.replace("_", " ").title()
            sock = node.inputs.get(sock_name)
            if sock is not None:
                val = prop_v.replace("_", " ").title() if (getattr(sock, "type", "") == "MENU" and isinstance(prop_v, str)) else prop_v
                try:
                    sock.default_value = val
                except (TypeError, ValueError):
                    pass
        for inp_k, inp_v in (nspec.get("inputs") or {}).items():
            sock = _resolve_socket(node.inputs, inp_k)
            if sock is None:
                valid_in = [s.name for s in node.inputs]
                return {"error": f"Unknown input socket '{inp_k}' on node '{ntype}'. Valid inputs: {valid_in}"}
            sock.default_value = inp_v
        created_nodes[nid] = node

    for lspec in links:
        fn = created_nodes.get(lspec["from_node"]) or nt.nodes.get(lspec["from_node"])
        tn = created_nodes.get(lspec["to_node"]) or nt.nodes.get(lspec["to_node"])
        if not fn or not tn:
            return {"error": f"Link references missing node: {lspec}"}
        out_sock = _resolve_socket(fn.outputs, lspec["from_socket"])
        if out_sock is None:
            return {"error": f"Unknown output socket '{lspec['from_socket']}' on '{fn.bl_idname}'. Valid: {[s.name for s in fn.outputs]}"}
        in_sock = _resolve_socket(tn.inputs, lspec["to_socket"])
        if in_sock is None:
            return {"error": f"Unknown input socket '{lspec['to_socket']}' on '{tn.bl_idname}'. Valid: {[s.name for s in tn.inputs]}"}
        nt.links.new(out_sock, in_sock)

    return {
        "tree_type": ttype,
        "target_name": target_name,
        "macro": macro,
        "nodes_created": len(created_nodes),
        "links_created": len(links),
    }

# --- rigging_anim.py ---
"""
Declarative Armature, IK, Bone Constraints, Analytical Envelope/KDTree Weight Binding,
and Pro Overlapping/Eased Animation Handlers for blender-kit v3.0.
"""
import math
from typing import Any, Dict, List, Optional

try:
    import bpy
    from mathutils import Vector
except ImportError:
    bpy = None
    Vector = None


def _point_to_segment_dist(p, a, b) -> float:
    ab = b - a
    len_sq = ab.length_squared
    if len_sq < 1e-10:
        return (p - a).length
    t = max(0.0, min(1.0, (p - a).dot(ab) / len_sq))
    proj = a + t * ab
    return (p - proj).length


def _bind_mesh_envelope_kdtree(mesh_obj, arm_obj, max_influences: int = 4) -> Dict[str, Any]:
    mesh = mesh_obj.data
    deform_bones = [b for b in arm_obj.data.bones if b.use_deform]
    if not deform_bones:
        deform_bones = list(arm_obj.data.bones)

    arm_mod = next((m for m in mesh_obj.modifiers if m.type == 'ARMATURE'), None)
    if not arm_mod:
        arm_mod = mesh_obj.modifiers.new(name="KIT_ARMATURE", type='ARMATURE')
    arm_mod.object = arm_obj

    vg_map = {}
    for b in deform_bones:
        vg = mesh_obj.vertex_groups.get(b.name) or mesh_obj.vertex_groups.new(name=b.name)
        vg_map[b.name] = vg

    mat_mesh_to_arm = arm_obj.matrix_world.inverted() @ mesh_obj.matrix_world
    segments = [(b.name, b.head_local.copy(), b.tail_local.copy()) for b in deform_bones]
    max_inf = max(1, int(max_influences))

    for v in mesh.vertices:
        p_arm = mat_mesh_to_arm @ v.co
        dists = []
        for bname, head, tail in segments:
            d = _point_to_segment_dist(p_arm, head, tail)
            dists.append((d, bname))
        dists.sort(key=lambda x: x[0])
        chosen = dists[:max_inf]
        raw_weights = [(1.0 / (max(d, 0.005) ** 2), bname) for d, bname in chosen]
        total_w = sum(w for w, _ in raw_weights)
        if total_w > 1e-8:
            for w, bname in raw_weights:
                norm_w = w / total_w
                if norm_w >= 0.01:
                    vg_map[bname].add([v.index], float(norm_w), 'REPLACE')

    return {"mesh": mesh_obj.name, "bind_mode": "ENVELOPE_KDTREE", "bones_bound": len(deform_bones), "max_influences": max_inf}


def kit_rig_build_armature(
    armature_name: str,
    collection_name: Optional[str] = None,
    bones: Optional[List[Dict[str, Any]]] = None,
    constraints: Optional[List[Dict[str, Any]]] = None,
    bind_meshes: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    bones = bones or []
    constraints = constraints or []
    bind_meshes = bind_meshes or []

    arm_obj = bpy.data.objects.get(armature_name)
    if not arm_obj or arm_obj.type != 'ARMATURE':
        arm_data = bpy.data.armatures.new(armature_name)
        arm_obj = bpy.data.objects.new(armature_name, arm_data)
        col = _get_or_create_collection(collection_name)
        col.objects.link(arm_obj)
    else:
        arm_data = arm_obj.data

    # 1. Batch EditBone creation inside atomic_context_guard
    if bones:
        with atomic_context_guard(arm_obj, mode="EDIT"):
            ebones = arm_data.edit_bones
            created_eb = {}
            for bspec in bones:
                bname = bspec["name"]
                eb = ebones.get(bname) or ebones.new(bname)
                eb.head = Vector(bspec.get("head", (0.0, 0.0, 0.0)))
                eb.tail = Vector(bspec.get("tail", (0.0, 0.0, 0.5)))
                eb.roll = math.radians(float(bspec.get("roll_deg", 0.0)))
                eb.use_deform = bool(bspec.get("use_deform", True))
                if "bbone_segments" in bspec:
                    eb.bbone_segments = max(1, int(bspec["bbone_segments"]))
                created_eb[bname] = eb

            for bspec in bones:
                parent_name = bspec.get("parent")
                if parent_name and parent_name in created_eb:
                    eb = created_eb[bspec["name"]]
                    eb.parent = created_eb[parent_name]
                    eb.use_connect = bool(bspec.get("use_connect", False))

    # 2. Attach PoseBone constraints in OBJECT mode
    bpy.context.view_layer.update()
    constraints_added = 0
    for cspec in constraints:
        bname = cspec.get("bone")
        pb = arm_obj.pose.bones.get(bname)
        if not pb:
            continue
        ctype = cspec.get("type", "IK").upper()
        con = pb.constraints.new(type=ctype)
        target_name = cspec.get("target_obj", armature_name)
        target_obj = bpy.data.objects.get(target_name) if target_name else arm_obj
        if hasattr(con, "target") and target_obj:
            con.target = target_obj
        if hasattr(con, "subtarget") and cspec.get("subtarget"):
            con.subtarget = str(cspec["subtarget"])
        if hasattr(con, "chain_count") and "chain_count" in cspec:
            con.chain_count = int(cspec["chain_count"])
        if hasattr(con, "pole_target") and cspec.get("pole_target"):
            con.pole_target = bpy.data.objects.get(cspec["pole_target"]) or arm_obj
        if hasattr(con, "pole_subtarget") and cspec.get("pole_subtarget"):
            con.pole_subtarget = str(cspec["pole_subtarget"])
        if hasattr(con, "pole_angle") and "pole_angle_deg" in cspec:
            con.pole_angle = math.radians(float(cspec["pole_angle_deg"]))
        if "influence" in cspec:
            con.influence = float(cspec["influence"])
        for sk, sv in (cspec.get("settings") or {}).items():
            if hasattr(con, sk):
                setattr(con, sk, sv)
        constraints_added += 1

    # 3. Bind meshes (Phase 2 Assembly or single-call rig)
    bound_results = []
    for bmesh_spec in bind_meshes:
        mname = bmesh_spec["mesh_name"] if isinstance(bmesh_spec, dict) else str(bmesh_spec)
        bmode = bmesh_spec.get("bind_mode", "ENVELOPE_KDTREE") if isinstance(bmesh_spec, dict) else "ENVELOPE_KDTREE"
        max_inf = int(bmesh_spec.get("max_influences", 4)) if isinstance(bmesh_spec, dict) else 4
        mobj = bpy.data.objects.get(mname)
        if not mobj or mobj.type != 'MESH':
            continue

        if bmode == "RIGID_BONE":
            bone_target = (bmesh_spec.get("bone") if isinstance(bmesh_spec, dict) else None) or (arm_data.bones[0].name if arm_data.bones else "Root")
            vg = mobj.vertex_groups.get(bone_target) or mobj.vertex_groups.new(name=bone_target)
            vg.add(list(range(len(mobj.data.vertices))), 1.0, 'REPLACE')
            arm_mod = next((m for m in mobj.modifiers if m.type == 'ARMATURE'), None) or mobj.modifiers.new(name="KIT_ARMATURE", type='ARMATURE')
            arm_mod.object = arm_obj
            bound_results.append({"mesh": mobj.name, "bind_mode": "RIGID_BONE", "bone": bone_target})
        elif bmode == "AUTO_HEAT":
            try:
                with atomic_context_guard(arm_obj, mode="OBJECT", extra_selected=[mobj]):
                    bpy.ops.object.parent_set(type='ARMATURE_AUTO')
                bound_results.append({"mesh": mobj.name, "bind_mode": "AUTO_HEAT"})
            except Exception:
                bound_results.append(_bind_mesh_envelope_kdtree(mobj, arm_obj, max_influences=max_inf))
        else:
            bound_results.append(_bind_mesh_envelope_kdtree(mobj, arm_obj, max_influences=max_inf))

    return {
        "armature": arm_obj.name,
        "total_bones": len(arm_data.bones),
        "constraints_added": constraints_added,
        "bound_meshes": bound_results,
    }


def kit_pro_motion(
    armature_name: str,
    clip_name: str = "idle_loop",
    motion_type: str = "overlapping_wave",
    frame_start: int = 1,
    frame_end: int = 48,
    amplitude_deg: float = 12.0,
    phase_step_rad: float = 0.65,
    set_scene_range: bool = False,
) -> Dict[str, Any]:
    arm = bpy.data.objects.get(armature_name)
    if not arm or arm.type != 'ARMATURE':
        return {"error": f"Armature '{armature_name}' not found"}

    if set_scene_range:
        bpy.context.scene.frame_start = int(frame_start)
        bpy.context.scene.frame_end = int(frame_end)

    if not arm.animation_data:
        arm.animation_data_create()

    act_name = f"AN_{arm.name}_{clip_name}"
    act = bpy.data.actions.get(act_name) or bpy.data.actions.new(name=act_name)
    act.use_fake_user = True
    arm.animation_data.action = act

    pbones = list(arm.pose.bones)
    duration = max(1, int(frame_end) - int(frame_start))

    if motion_type == "attack_anticipation":
        phases = [
            (0.00, 0.00),
            (0.25, -0.45),
            (0.55, 1.25),
            (0.80, -0.12),
            (1.00, 0.00),
        ]
        for ratio, mult in phases:
            f = int(round(frame_start + duration * ratio))
            for bi, pb in enumerate(pbones):
                pb.rotation_mode = 'XYZ'
                w = min(1.3, 0.4 + 0.15 * bi)
                ang_x = math.radians(amplitude_deg * mult * w)
                pb.rotation_euler = (ang_x, 0.0, 0.0)
                pb.keyframe_insert(data_path="rotation_euler", frame=f)
    else:
        num_steps = 8
        for step in range(num_steps + 1):
            f = int(round(frame_start + (duration * step / num_steps)))
            phase_base = 2.0 * math.pi * (step / num_steps)
            for bi, pb in enumerate(pbones):
                pb.rotation_mode = 'XYZ'
                weight_along_chain = min(1.4, 0.35 + 0.12 * bi)
                ang_z = math.radians(amplitude_deg * weight_along_chain) * math.sin(phase_base - bi * phase_step_rad)
                ang_x = math.radians(amplitude_deg * 0.45 * weight_along_chain) * math.cos(phase_base - bi * phase_step_rad)
                if motion_type == "floating_idle" and bi == 0:
                    pb.location = (0.0, 0.0, 0.06 * math.sin(phase_base))
                    pb.keyframe_insert(data_path="location", frame=f)
                pb.rotation_euler = (ang_x, 0.0, ang_z)
                pb.keyframe_insert(data_path="rotation_euler", frame=f)

    for fc in getattr(act, "fcurves", []):
        for kp in fc.keyframe_points:
            kp.interpolation = 'BEZIER'
            kp.handle_left_type = 'AUTO_CLAMPED'
            kp.handle_right_type = 'AUTO_CLAMPED'

    return {
        "armature": arm.name,
        "action": act.name,
        "motion_type": motion_type,
        "bones_keyed": len(pbones),
        "frames": [frame_start, frame_end],
        "loop_closed": True,
    }


anim_pro_motion = kit_pro_motion

# --- audits.py ---
"""
Context-Free Isolated Audit Engine for blender-kit v3.0.
Evaluates mesh, dual-target topology (game_realtime vs film_cinematic), UV bleed,
visual match, rig weights, and animation loop closure on explicit object lists
without reading or mutating bpy.context.selected_objects or active_object.
"""
import json
import math
from pathlib import Path
from typing import Any, Dict, List, Optional

try:
    import bpy
    import bmesh
    from mathutils import Vector
except ImportError:
    bpy = None
    bmesh = None
    Vector = None


def _resolve_target_meshes(target_objects: Optional[List[str]] = None) -> List[Any]:
    if bpy is None or not getattr(bpy, "context", None):
        return []
    if target_objects:
        return [
            bpy.data.objects[name]
            for name in target_objects
            if name in bpy.data.objects and bpy.data.objects[name].type == "MESH"
        ]
    return [o for o in bpy.context.scene.objects if o.type == "MESH" and o.visible_get()]


def _audit_mesh_isolated(objs: List[Any], budget: int = 0) -> Dict[str, Any]:
    dg = bpy.context.evaluated_depsgraph_get()
    rows = []
    total_tris = 0
    for o in objs:
        bm = bmesh.new()
        bm.from_object(o, dg)
        bm.verts.ensure_lookup_table()
        bm.edges.ensure_lookup_table()
        bm.faces.ensure_lookup_table()

        tris = sum(len(f.verts) - 2 for f in bm.faces)
        ngons = sum(1 for f in bm.faces if len(f.verts) > 4)
        non_manifold = sum(1 for e in bm.edges if not e.is_manifold and not e.is_boundary)
        loose_verts = sum(1 for v in bm.verts if not v.link_edges)
        total_tris += tris
        bm.free()

        scale_ok = all(abs(s - 1.0) < 1e-4 for s in o.scale)
        rot_ok = all(abs(r) < 1e-4 for r in o.rotation_euler)
        obj_pass = (ngons == 0 and non_manifold == 0 and loose_verts == 0 and scale_ok and rot_ok)
        rows.append({
            "object": o.name,
            "tris": tris,
            "ngons": ngons,
            "non_manifold": non_manifold,
            "loose_verts": loose_verts,
            "transforms_applied": scale_ok and rot_ok,
            "pass": obj_pass,
        })

    budget_ok = (budget <= 0) or (total_tris <= budget)
    return {
        "audit": "mesh",
        "total_tris": total_tris,
        "budget": budget,
        "budget_ok": budget_ok,
        "objects": rows,
        "pass": all(r["pass"] for r in rows) and budget_ok,
    }


def _audit_topology_isolated(
    objs: List[Any],
    target_mode: str = "game_realtime",
    armature_name: Optional[str] = None,
) -> Dict[str, Any]:
    curved_angle_rad = math.radians(2.5)
    rows = []
    for o in objs:
        bm = bmesh.new()
        bm.from_mesh(o.data)
        bm.verts.ensure_lookup_table()
        bm.edges.ensure_lookup_table()
        bm.faces.ensure_lookup_table()

        quads = sum(1 for f in bm.faces if len(f.verts) == 4)
        tris = sum(1 for f in bm.faces if len(f.verts) == 3)
        ngons = sum(1 for f in bm.faces if len(f.verts) > 4)
        curved_surface_tris = sum(
            1 for f in bm.faces
            if len(f.verts) == 3 and any(
                len(e.link_faces) == 2 and e.calc_face_angle(0.0) > curved_angle_rad
                for e in f.edges
            )
        )
        closed_manifold = all(e.is_manifold for e in bm.edges)
        all_quads = (tris == 0 and ngons == 0)
        pole_balance = sum(4 - len(v.link_edges) for v in bm.verts)
        pole_balance_ok = (pole_balance % 8 == 0) if (closed_manifold and all_quads) else True

        joint_poles = 0
        arm = bpy.data.objects.get(armature_name) if armature_name else (o.parent if o.parent and o.parent.type == "ARMATURE" else None)
        if arm is not None and arm.type == "ARMATURE":
            m_to_obj = o.matrix_world.inverted() @ arm.matrix_world
            jpts = [m_to_obj @ b.head_local for b in arm.data.bones if b.parent]
            for v in bm.verts:
                if not v.is_boundary and len(v.link_edges) != 4:
                    if any((v.co - jp).length <= 0.08 for jp in jpts):
                        joint_poles += 1

        bm.free()

        if target_mode == "film_cinematic":
            has_subd = any(m.type == "SUBSURF" for m in o.modifiers)
            obj_pass = (ngons == 0 and curved_surface_tris == 0 and pole_balance_ok and has_subd)
        else:
            obj_pass = (ngons == 0 and joint_poles == 0)

        rows.append({
            "object": o.name,
            "target_mode": target_mode,
            "quads": quads,
            "tris": tris,
            "ngons": ngons,
            "curved_surface_tris": curved_surface_tris,
            "pole_balance": pole_balance,
            "pole_balance_multiple_of_8": pole_balance_ok,
            "poles_near_joints": joint_poles,
            "pass": obj_pass,
        })

    return {"audit": "topology", "target_mode": target_mode, "objects": rows, "pass": all(r["pass"] for r in rows)}


def _audit_visual_match_isolated(objs: List[Any], ref_aspect_xz: float = 0.0) -> Dict[str, Any]:
    rows = []
    for obj in objs:
        mesh = obj.data
        bbox = [obj.matrix_world @ Vector(c) for c in obj.bound_box]
        xs = [v.x for v in bbox]
        ys = [v.y for v in bbox]
        zs = [v.z for v in bbox]
        dx = max(xs) - min(xs)
        dy = max(ys) - min(ys)
        dz = max(zs) - min(zs)
        aspect_xz = round(dx / max(dz, 1e-5), 3)
        aspect_yz = round(dy / max(dz, 1e-5), 3)

        bleed_faces = 0
        uv_layer = mesh.uv_layers.active
        img = None
        if mesh.materials:
            mat = mesh.materials[0]
            if mat and mat.use_nodes:
                for n in mat.node_tree.nodes:
                    if n.type == "TEX_IMAGE" and n.image:
                        img = n.image
                        break

        if uv_layer and img and img.size[0] > 0 and img.size[1] > 0:
            W, H = img.size
            px = img.pixels[:]
            uv_data = uv_layer.data
            for poly in mesh.polygons:
                cols = []
                for li in poly.loop_indices:
                    uv = uv_data[li].uv
                    ix = min(W - 1, max(0, int(uv[0] * W)))
                    iy = min(H - 1, max(0, int(uv[1] * H)))
                    base = (iy * W + ix) * 4
                    cols.append((px[base], px[base + 1], px[base + 2]))
                if cols:
                    r_span = max(c[0] for c in cols) - min(c[0] for c in cols)
                    g_span = max(c[1] for c in cols) - min(c[1] for c in cols)
                    b_span = max(c[2] for c in cols) - min(c[2] for c in cols)
                    if max(r_span, g_span, b_span) > 0.25:
                        bleed_faces += 1

        bleed_ratio = round(bleed_faces / max(1, len(mesh.polygons)), 4)
        aspect_ok = True
        if ref_aspect_xz > 0:
            aspect_ok = abs(aspect_xz - ref_aspect_xz) <= 0.25 * ref_aspect_xz

        rows.append({
            "object": obj.name,
            "dimensions_m": [round(dx, 3), round(dy, 3), round(dz, 3)],
            "aspect_xz": aspect_xz,
            "aspect_yz": aspect_yz,
            "bleed_faces": bleed_faces,
            "bleed_ratio": bleed_ratio,
            "has_custom_normals": mesh.has_custom_normals,
            "pass": (bleed_ratio <= 0.05) and aspect_ok,
        })

    return {"audit": "visual_match", "objects": rows, "pass": all(r["pass"] for r in rows)}


def _audit_uv_isolated(
    objs: List[Any],
    texture_px: int = 1024,
    target_density: float = 256.0,
    tolerance: float = 0.20,
) -> Dict[str, Any]:
    rows = []
    for obj in objs:
        bm = bmesh.new()
        bm.from_mesh(obj.data)
        uv = bm.loops.layers.uv.active
        if uv is None:
            rows.append({
                "object": obj.name,
                "has_uv": False,
                "pass": False,
                "failed": ["no_uv"],
            })
            bm.free()
            continue

        s = obj.matrix_world.to_scale()
        scale_factor = abs(s.x * s.y * s.z) ** (2.0 / 3.0) if (s.x and s.y and s.z) else 1.0
        world_area = 0.0
        uv_area = 0.0
        out_of_bounds = 0
        for f in bm.faces:
            world_area += f.calc_area() * scale_factor
            pts = [l[uv].uv.copy() for l in f.loops]
            for p in pts:
                if p.x < -1e-3 or p.x > 1.001 or p.y < -1e-3 or p.y > 1.001:
                    out_of_bounds += 1
            a = 0.0
            for i in range(len(pts)):
                x1, y1 = pts[i]
                x2, y2 = pts[(i + 1) % len(pts)]
                a += x1 * y2 - x2 * y1
            uv_area += abs(a) * 0.5
        bm.free()

        density = float(texture_px) * math.sqrt(uv_area / world_area) if (world_area > 0 and uv_area > 0) else 0.0
        density_ok = (target_density <= 0) or (target_density * (1.0 - tolerance) <= density <= target_density * (1.0 + tolerance))
        bounds_ok = (out_of_bounds == 0)
        failed = []
        if not density_ok:
            failed.append("texel_density_out_of_tolerance")
        if not bounds_ok:
            failed.append("uv_out_of_0_1_bounds")
        rows.append({
            "object": obj.name,
            "has_uv": True,
            "uv_area_sum": round(uv_area, 4),
            "world_area_m2": round(world_area, 4),
            "texel_density_px_per_m": round(density, 1),
            "target_density_px_per_m": target_density,
            "out_of_bounds_uvs": out_of_bounds,
            "failed": failed,
            "pass": density_ok and bounds_ok,
        })
    return {"audit": "uv", "objects": rows, "pass": bool(rows) and all(r["pass"] for r in rows)}


def _audit_anim_isolated(loop_suffix: str = "_loop", root_bone: Optional[str] = None) -> Dict[str, Any]:
    fps = bpy.context.scene.render.fps if (bpy and getattr(bpy, "context", None)) else 30
    actions_out = []
    for a in getattr(bpy.data, "actions", []):
        f0, f1 = a.frame_range
        row: Dict[str, Any] = {
            "action": a.name,
            "frame_start": f0,
            "frame_end": f1,
            "frames": int(f1 - f0) + 1,
            "duration_s": round((f1 - f0) / max(1, fps), 3),
        }
        if a.name.endswith(loop_suffix) and hasattr(a, "fcurves"):
            bad = []
            for fc in a.fcurves:
                d = abs(fc.evaluate(f0) - fc.evaluate(f1))
                if d > 1e-3:
                    bad.append({"channel": f"{fc.data_path}[{fc.array_index}]", "diff": round(d, 4)})
            row["loop_open_channels"] = bad[:20]
            row["loop_closed"] = not bad
        if root_bone and hasattr(a, "fcurves"):
            p = f'pose.bones["{root_bone}"].location'
            row["root_location_drift_xyz"] = [round(fc.evaluate(f1) - fc.evaluate(f0), 4) for fc in a.fcurves if fc.data_path == p]
        actions_out.append(row)
    return {
        "audit": "anim",
        "fps": fps,
        "actions": actions_out,
        "pass": all(r.get("loop_closed", True) for r in actions_out) and len(actions_out) > 0,
    }


def _audit_naming_isolated(objs: List[Any]) -> Dict[str, Any]:
    bad = []
    for o in objs:
        if o.type == "MESH" and not o.name.startswith(("SM_", "SK_", ".kit_cage_")):
            bad.append({"kind": "object", "name": o.name, "expected_prefix": ["SM_", "SK_"]})
        for slot in getattr(o, "material_slots", []):
            if slot.material and not slot.material.name.startswith("MAT_"):
                bad.append({"kind": "material", "name": slot.material.name, "expected_prefix": ["MAT_"]})
    return {"audit": "naming", "violations": bad, "pass": len(bad) == 0}


def _audit_rig_isolated(objs: List[Any], armature_name: Optional[str] = None, target_mode: str = "game_realtime") -> Dict[str, Any]:
    arm = bpy.data.objects.get(armature_name) if armature_name else next((o for o in bpy.context.scene.objects if o.type == "ARMATURE"), None)
    if not arm or arm.type != "ARMATURE":
        return {"audit": "rig", "pass": False, "error": "No armature found"}

    max_inf_limit = 8 if target_mode == "film_cinematic" else 4
    deform_names = {b.name for b in arm.data.bones if b.use_deform}
    over_inf_total = 0
    unweighted_total = 0

    for m in objs:
        gnames = {g.index: g.name for g in m.vertex_groups}
        for v in m.data.vertices:
            w = [g.weight for g in v.groups if g.group in gnames and gnames[g.group] in deform_names and g.weight > 1e-4]
            if not w:
                unweighted_total += 1
            if len(w) > max_inf_limit:
                over_inf_total += 1

    passed = (unweighted_total == 0 and over_inf_total == 0)
    return {
        "audit": "rig",
        "armature": arm.name,
        "bones": len(arm.data.bones),
        "deform_bones": len(deform_names),
        "max_influences_limit": max_inf_limit,
        "unweighted_verts": unweighted_total,
        "over_influence_verts": over_inf_total,
        "pass": passed,
    }


def kit_audit_run_isolated(
    audit_type: str = "all",
    target_objects: Optional[List[str]] = None,
    target_mode: str = "game_realtime",
    budget: int = 0,
    armature_name: Optional[str] = None,
    ref_aspect_xz: float = 0.0,
    asset_name: str = "Scene",
    texture_px: int = 1024,
    target_density: float = 256.0,
) -> Dict[str, Any]:
    objs = _resolve_target_meshes(target_objects)
    atype = audit_type.lower()
    results: Dict[str, Any] = {}

    if atype in ("mesh", "all"):
        results["mesh"] = _audit_mesh_isolated(objs, budget=budget)
    if atype in ("topology", "all"):
        results["topology"] = _audit_topology_isolated(objs, target_mode=target_mode, armature_name=armature_name)
    if atype == "uv":
        results["uv"] = _audit_uv_isolated(objs, texture_px=texture_px, target_density=target_density)
    if atype in ("visual_match", "all"):
        results["visual_match"] = _audit_visual_match_isolated(objs, ref_aspect_xz=ref_aspect_xz)
    if atype == "rig" or (atype == "all" and armature_name):
        results["rig"] = _audit_rig_isolated(objs, armature_name=armature_name, target_mode=target_mode)
    if atype == "anim":
        results["anim"] = _audit_anim_isolated()
    if atype == "naming":
        results["naming"] = _audit_naming_isolated(objs)

    overall_pass = all(sub.get("pass", True) for sub in results.values())
    payload = {
        "asset_name": asset_name,
        "audit_type": atype,
        "target_mode": target_mode,
        "pass": overall_pass,
        "results": results,
    }

    try:
        asset_dir = Path(resolve_session_dir(asset_name, target_mode=target_mode))
        audit_file = asset_dir / "audit" / f"audit_{atype}.json"
        audit_file.write_text(json.dumps(payload, indent=2), encoding="utf-8")
        payload["report_path"] = str(audit_file)
    except Exception:
        pass

    return payload

